from heapq import heappop, heappush


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    C = capacity + 1
    K = max_swaps + 1
    total_states = n * C * K

    SWAP_SHIFT = max_swaps.bit_length()
    STATE_SHIFT = total_states.bit_length()
    STATE_MASK = (1 << STATE_SHIFT) - 1
    INF = 1 << 60

    is_station = [False] * n
    for x in stations:
        is_station[x] = True

    # Group roads by (u, v) and prune dominated parallel roads and useless self-loops
    by_pair = [{} for _ in range(n)]
    for u, v, m, e in roads:
        if u == v and e >= 0:
            continue
        d = by_pair[u]
        if v not in d:
            d[v] = [(e, m)]
        else:
            d[v].append((e, m))

    adj = [[] for _ in range(n)]
    for u in range(n):
        lst = []
        for v, ems in by_pair[u].items():
            vk = v * K
            if len(ems) > 1:
                ems.sort()
                min_m = INF
                for e, m in ems:
                    if m < min_m:
                        min_m = m
                        lst.append((e, vk, m << SWAP_SHIFT))
            else:
                e, m = ems[0]
                lst.append((e, vk, m << SWAP_SHIFT))
        lst.sort()  # Sort by energy ascending for early break
        adj[u] = lst

    dist = [INF] * total_states
    max_c = [-1] * (n * K)

    start_state = (s * K) * C + capacity
    dist[start_state] = 0
    pq = [start_state]  # cost is 0

    swap_cost_add = (swap_time << SWAP_SHIFT) + 1

    while pq:
        item = heappop(pq)
        cost = item >> STATE_SHIFT
        state = item & STATE_MASK

        uk, c = divmod(state, C)
        if c <= max_c[uk]:
            continue

        u, k = divmod(uk, K)
        if u == t:
            return (cost >> SWAP_SHIFT, k)

        # Record dominance for (u, kk) for all kk >= k
        base_uk = uk - k
        for kk in range(k, K):
            idx = base_uk + kk
            if c > max_c[idx]:
                max_c[idx] = c
            else:
                break

        # Option 1: Swap battery at station u
        if is_station[u] and k < max_swaps and c < capacity:
            nuk = uk + 1
            if capacity > max_c[nuk]:
                nstate = nuk * C + capacity
                ncost = cost + swap_cost_add
                if ncost < dist[nstate]:
                    dist[nstate] = ncost
                    heappush(pq, (ncost << STATE_SHIFT) | nstate)

        # Option 2: Drive an outgoing road
        for e, vk, ms in adj[u]:
            if e > c:
                break
            nc = c - e
            if nc > capacity:
                nc = capacity
            nuk = vk + k
            if nc <= max_c[nuk]:
                continue
            nstate = nuk * C + nc
            ncost = cost + ms
            if ncost < dist[nstate]:
                dist[nstate] = ncost
                heappush(pq, (ncost << STATE_SHIFT) | nstate)

    return None

from collections import deque


def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    neg_inf = -(10**18)

    # dp[i + 1][w] = max score ending with message i kept (i = -1 is empty prefix)
    # and total kept length equal to w.
    dp = [[neg_inf] * (budget + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    # For each weight w, queues[w] maintains a monotonic decreasing queue of
    # (i, dp[i + 1][w]) for i in the non-adjacent valid window [L_j, j - 2].
    queues = [deque() for _ in range(budget + 1)]
    last_pinned = -1

    for j in range(n):
        if j >= 1:
            p = j - 2
            dp_p = dp[p + 1]
            for w in range(budget + 1):
                v = dp_p[w]
                if v > neg_inf:
                    q = queues[w]
                    while q and q[-1][1] <= v:
                        q.pop()
                    q.append((p, v))

        len_j, val_j, pinned_j = messages[j]
        L_j = max(-1, j - 1 - max_gap, last_pinned)

        if len_j <= budget:
            dp_j = dp[j + 1]
            if j == 0:
                dp_j[len_j] = val_j
            else:
                dp_prev = dp[j]
                limit = budget - len_j
                for w in range(limit + 1):
                    best = neg_inf
                    vp = dp_prev[w]
                    if vp > neg_inf:
                        best = vp + bonus
                    q = queues[w]
                    while q and q[0][0] < L_j:
                        q.popleft()
                    if q and q[0][1] > best:
                        best = q[0][1]
                    if best > neg_inf:
                        dp_j[w + len_j] = best + val_j

        if pinned_j:
            last_pinned = j

    L_n = max(-1, n - 1 - max_gap, last_pinned)
    ans = neg_inf
    for idx in range(L_n + 1, n + 1):
        row_max = max(dp[idx])
        if row_max > ans:
            ans = row_max

    return None if ans == neg_inf else ans

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Top-down traversal (BFS order) from root 0
    order = [0]
    idx = 0
    while idx < len(order):
        u = order[idx]
        idx += 1
        order.extend(children[u])

    # Propagate ancestor capacity bounds downward
    eff_cap = [0] * n
    eff_cap[0] = root_cap
    for u in order:
        if u != 0:
            eff_cap[u] = min(cap[u], eff_cap[parent[u]])

    INF = 10**18
    subtree_demand = [0] * n
    must_retain = [False] * n
    # opt[v] stores a sorted list of (load, min_cost) pairs that v can contribute to parent[v]
    opt = [None] * n

    # Bottom-up DP
    for v in reversed(order):
        sub_d = demand[v]
        mr = critical[v] or (v == 0)
        for c in children[v]:
            sub_d += subtree_demand[c]
            if must_retain[c]:
                mr = True
        subtree_demand[v] = sub_d
        must_retain[v] = mr

        limit = min(eff_cap[v], sub_d)

        if demand[v] > limit:
            valid_v = []
        else:
            valid_v = [(demand[v], 0)]
            # Merge smaller option lists first for speed
            for c in sorted(children[v], key=lambda x: len(opt[x])):
                opt_c = opt[c]
                if not opt_c:
                    valid_v = []
                    break
                new_max = min(limit, valid_v[-1][0] + opt_c[-1][0])
                new_dp = [INF] * (new_max + 1)
                for i, ci in valid_v:
                    for j, cj in opt_c:
                        ij = i + j
                        if ij > new_max:
                            break
                        val = ci + cj
                        if val < new_dp[ij]:
                            new_dp[ij] = val
                valid_v = [(k, val) for k, val in enumerate(new_dp) if val < INF]
                if not valid_v:
                    break

        if v == 0:
            if not valid_v:
                return None
            return min(val for _, val in valid_v)

        if not mr:
            cut_v = cut_cost[v] + penalty * sub_d
            if valid_v and valid_v[0][0] == 0:
                if cut_v < valid_v[0][1]:
                    valid_v[0] = (0, cut_v)
            else:
                valid_v.insert(0, (0, cut_v))

        opt[v] = valid_v

def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings == 0 or not connections:
        return None

    # Group connections by trip_id and compute a safe infinity bound.
    trip_map = {}
    trips = []
    max_arr = 0
    for trip_id, u, v, dep, arr in connections:
        if arr > max_arr:
            max_arr = arr
        tid = trip_map.get(trip_id)
        if tid is None:
            tid = len(trips)
            trip_map[trip_id] = tid
            trips.append([(dep, u, v, arr)])
        else:
            trips[tid].append((dep, u, v, arr))

    max_transfer = max(transfer) if transfer else 0
    INF = max(start_time, max_arr) + max_transfer + 1

    n_stations = len(transfer)
    departures = [[] for _ in range(n_stations)]

    # Sort each trip's connections chronologically and index departures per station.
    for tid, t_conns in enumerate(trips):
        if len(t_conns) > 1:
            t_conns.sort()
        for idx, (dep, u, v, arr) in enumerate(t_conns):
            departures[u].append((dep, tid, idx))

    # Sort each station's departures ascending by dep so we can pop >= ready[u] from the end.
    for dep_list in departures:
        if len(dep_list) > 1:
            dep_list.sort()

    ready = [INF] * n_stations
    ready[source] = start_time
    active = [source]
    earliest_boarded = [len(t) for t in trips]
    best_target = INF

    for _ in range(max_boardings):
        pending = {}
        for u in active:
            r_u = ready[u]
            if r_u >= best_target:
                continue
            dep_list = departures[u]
            while dep_list and dep_list[-1][0] >= r_u:
                _, tid, idx = dep_list.pop()
                eb = earliest_boarded[tid]
                if idx < eb:
                    t_conns = trips[tid]
                    for j in range(idx, eb):
                        _, _, v, arr = t_conns[j]
                        if arr >= best_target:
                            break
                        if v == target:
                            best_target = arr
                            break
                        nr = arr + transfer[v]
                        if nr < best_target and nr < ready[v]:
                            prev = pending.get(v)
                            if prev is None or nr < prev:
                                pending[v] = nr
                    earliest_boarded[tid] = idx

        if not pending:
            break
        active = list(pending.keys())
        for v, nr in pending.items():
            ready[v] = nr

    return None if best_target == INF else best_target

from collections import deque


class _Resource:
    __slots__ = ("name", "s_holders", "x_holder", "head", "tail", "up_tail")

    def __init__(self, name):
        self.name = name
        self.s_holders = set()
        self.x_holder = None
        self.head = None
        self.tail = None
        self.up_tail = None


def run_lock_manager(ops):
    STEP = 1 << 40
    log = []
    resources = {}
    tx_state = {}
    tx_locks = {}
    tx_wait = {}
    q_prev = {}
    q_next = {}
    ord_map = {}

    def get_res(name):
        r = resources.get(name)
        if r is None:
            r = _Resource(name)
            resources[name] = r
        return r

    def enqueue(tx, res, is_upgrade):
        if is_upgrade:
            p = res.up_tail
            if p is not None:
                n = q_next[p]
                q_prev[tx] = p
                q_next[tx] = n
                q_next[p] = tx
                if n is not None:
                    q_prev[n] = tx
                else:
                    res.tail = tx
                res.up_tail = tx
            else:
                n = res.head
                q_prev[tx] = None
                q_next[tx] = n
                if n is not None:
                    q_prev[n] = tx
                else:
                    res.tail = tx
                res.head = tx
                res.up_tail = tx
        else:
            p = res.tail
            q_prev[tx] = p
            q_next[tx] = None
            if p is not None:
                q_next[p] = tx
            else:
                res.head = tx
            res.tail = tx

    def remove_from_queue(tx, res):
        p = q_prev.pop(tx)
        n = q_next.pop(tx)
        if p is not None:
            q_next[p] = n
        else:
            res.head = n
        if n is not None:
            q_prev[n] = p
        else:
            res.tail = p
        if res.up_tail == tx:
            res.up_tail = p

    def renumber():
        nodes = sorted(ord_map, key=ord_map.__getitem__)
        for idx, u in enumerate(nodes, 1):
            ord_map[u] = idx * STEP

    def release(tx, op_idx):
        affected = set()
        w = tx_wait.pop(tx, None)
        if w is not None:
            w_res, _, _ = w
            remove_from_queue(tx, w_res)
            ord_map.pop(tx, None)
            affected.add(w_res)
        locks = tx_locks[tx]
        for res, mode in locks.items():
            if mode == "S":
                res.s_holders.remove(tx)
            else:
                res.x_holder = None
            affected.add(res)
        locks.clear()

        for res in sorted(affected, key=lambda r: r.name):
            while res.head is not None:
                u = res.head
                _, mode_u, is_upg = tx_wait[u]
                if mode_u == "S":
                    grantable = res.x_holder is None
                else:
                    if is_upg:
                        grantable = res.x_holder is None and len(res.s_holders) == 1
                    else:
                        grantable = res.x_holder is None and not res.s_holders
                if not grantable:
                    break
                remove_from_queue(u, res)
                del tx_wait[u]
                ord_map.pop(u, None)
                tx_state[u] = "ACTIVE"
                if mode_u == "S":
                    res.s_holders.add(u)
                    tx_locks[u][res] = "S"
                else:
                    if is_upg:
                        res.s_holders.remove(u)
                    res.x_holder = u
                    tx_locks[u][res] = "X"
                log.append(("GRANT", op_idx, u, res.name, mode_u))

    def resolve_deadlocks(tx, op_idx):
        while tx_state[tx] == "WAITING":
            in_w = set()
            nxt = q_next[tx]
            if nxt is not None and nxt in ord_map:
                in_w.add(nxt)
            for r, m_t in tx_locks[tx].items():
                y = r.head
                if y is not None and y in ord_map:
                    _, m_y, _ = tx_wait[y]
                    if m_y == "X" or m_t == "X":
                        in_w.add(y)

            out_w = set()
            t_res, t_mode, _ = tx_wait[tx]
            if t_res.head == tx:
                if t_mode == "S":
                    v = t_res.x_holder
                    if v is not None and v in ord_map:
                        out_w.add(v)
                else:
                    for v in t_res.s_holders:
                        if v in ord_map:
                            out_w.add(v)
                    v = t_res.x_holder
                    if v is not None and v in ord_map:
                        out_w.add(v)
            else:
                v = q_prev[tx]
                if v is not None and v in ord_map:
                    out_w.add(v)

            if not in_w and not out_w:
                ord_map[tx] = 0
                break
            if not in_w:
                ord_map[tx] = min(ord_map[v] for v in out_w) - STEP
                break
            if not out_w:
                ord_map[tx] = max(ord_map[u] for u in in_w) + STEP
                break

            max_in = max(ord_map[u] for u in in_w)
            min_out = min(ord_map[v] for v in out_w)

            if max_in < min_out:
                if min_out - max_in <= 1:
                    renumber()
                    max_in = max(ord_map[u] for u in in_w)
                    min_out = min(ord_map[v] for v in out_w)
                ord_map[tx] = (max_in + min_out) // 2
                break

            F = set()
            bfs = deque()
            for v in out_w:
                if ord_map[v] <= max_in:
                    F.add(v)
                    bfs.append(v)

            has_cycle = False
            while bfs:
                u = bfs.popleft()
                if u in in_w:
                    has_cycle = True
                r_u, m_u, _ = tx_wait[u]
                if r_u.head == u:
                    if m_u == "S":
                        v = r_u.x_holder
                        if v in ord_map and ord_map[v] <= max_in and v not in F:
                            F.add(v)
                            bfs.append(v)
                    else:
                        for v in r_u.s_holders:
                            if v in ord_map and ord_map[v] <= max_in and v not in F:
                                F.add(v)
                                bfs.append(v)
                        v = r_u.x_holder
                        if v in ord_map and ord_map[v] <= max_in and v not in F:
                            F.add(v)
                            bfs.append(v)
                else:
                    v = q_prev[u]
                    if v in ord_map and ord_map[v] <= max_in and v not in F:
                        F.add(v)
                        bfs.append(v)

            if has_cycle:
                scc = set()
                bfs = deque()
                for u in in_w:
                    if u in F:
                        scc.add(u)
                        bfs.append(u)
                while bfs:
                    w = bfs.popleft()
                    y = q_next[w]
                    if y in F and y not in scc:
                        scc.add(y)
                        bfs.append(y)
                    for r, m_w in tx_locks[w].items():
                        y = r.head
                        if y in F and y not in scc:
                            _, m_y, _ = tx_wait[y]
                            if m_y == "X" or m_w == "X":
                                scc.add(y)
                                bfs.append(y)
                victim = max(scc)
                if tx > victim:
                    victim = tx
                log.append(("ABORT", op_idx, victim))
                release(victim, op_idx)
                tx_state[victim] = "FINISHED"
            else:
                B = set()
                bfs = deque()
                for u in in_w:
                    if ord_map[u] >= min_out:
                        B.add(u)
                        bfs.append(u)
                while bfs:
                    w = bfs.popleft()
                    y = q_next[w]
                    if y in ord_map and ord_map[y] >= min_out and y not in B:
                        B.add(y)
                        bfs.append(y)
                    for r, m_w in tx_locks[w].items():
                        y = r.head
                        if y in ord_map and ord_map[y] >= min_out and y not in B:
                            _, m_y, _ = tx_wait[y]
                            if m_y == "X" or m_w == "X":
                                B.add(y)
                                bfs.append(y)
                B_list = sorted(B, key=ord_map.__getitem__)
                F_list = sorted(F, key=ord_map.__getitem__)
                vals = sorted(ord_map[x] for x in B_list + F_list)
                split = len(B_list)
                if vals[split] - vals[split - 1] <= 1:
                    renumber()
                    vals = sorted(ord_map[x] for x in B_list + F_list)
                for idx, x in enumerate(B_list):
                    ord_map[x] = vals[idx]
                ord_map[tx] = (vals[split - 1] + vals[split]) // 2
                for idx, x in enumerate(F_list):
                    ord_map[x] = vals[split + idx]
                break

    for i, op in enumerate(ops):
        kind = op[0]
        tx = op[1]
        st = tx_state.get(tx)
        if st is None:
            tx_state[tx] = "ACTIVE"
            tx_locks[tx] = {}
        elif st != "ACTIVE":
            log.append(("IGNORED", i, tx))
            continue

        if kind == "COMMIT":
            log.append(("COMMIT", i, tx))
            release(tx, i)
            tx_state[tx] = "FINISHED"
            continue

        res = get_res(op[2])
        mode = kind
        cur = tx_locks[tx].get(res)
        if cur == "X" or (cur == "S" and mode == "S"):
            log.append(("HELD", i, tx, res.name))
        elif cur == "S":
            if res.x_holder is None and len(res.s_holders) == 1:
                res.s_holders.remove(tx)
                res.x_holder = tx
                tx_locks[tx][res] = "X"
                log.append(("GRANT", i, tx, res.name, "X"))
            else:
                enqueue(tx, res, True)
                tx_state[tx] = "WAITING"
                tx_wait[tx] = (res, "X", True)
                log.append(("WAIT", i, tx, res.name, "X"))
                resolve_deadlocks(tx, i)
        else:
            if mode == "S":
                compat = res.x_holder is None
            else:
                compat = res.x_holder is None and not res.s_holders
            if res.head is None and compat:
                if mode == "S":
                    res.s_holders.add(tx)
                else:
                    res.x_holder = tx
                tx_locks[tx][res] = mode
                log.append(("GRANT", i, tx, res.name, mode))
            else:
                enqueue(tx, res, False)
                tx_state[tx] = "WAITING"
                tx_wait[tx] = (res, mode, False)
                log.append(("WAIT", i, tx, res.name, mode))
                resolve_deadlocks(tx, i)

    return log

import re

_NAME_RE = re.compile(r"[a-z0-9_]+", re.ASCII)
_ACTION_WORD_RE = re.compile(r"[a-z]+", re.ASCII)
_ACTION_RE = re.compile(r"[a-z]+(?:,[a-z]+)*", re.ASCII)
_SEG_PAT_RE = re.compile(r"\*\*|\*|[a-z0-9._-]+", re.ASCII)
_PATH_SEG_RE = re.compile(r"[a-z0-9._-]+", re.ASCII)


def _compile_block(block: list[str]) -> tuple[int, tuple[tuple[int, str], ...]]:
    return len(block), tuple((idx, seg) for idx, seg in enumerate(block) if seg != "*")


def _compile_resource(segs: list[str]):
    L = 0
    has_double = False
    for s in segs:
        if s == "**":
            has_double = True
        elif s != "*":
            L += 1

    if not has_double:
        exact = tuple((idx, s) for idx, s in enumerate(segs) if s != "*")
        return L, False, len(segs), exact, None, None

    raw_blocks: list[list[str]] = []
    cur: list[str] = []
    for s in segs:
        if s == "**":
            raw_blocks.append(cur)
            cur = []
        else:
            cur.append(s)
    raw_blocks.append(cur)

    prefix = _compile_block(raw_blocks[0])
    suffix = _compile_block(raw_blocks[-1])
    middle = tuple(_compile_block(b) for b in raw_blocks[1:-1] if b)
    min_len = prefix[0] + suffix[0] + sum(b[0] for b in middle)
    return L, True, min_len, prefix, suffix, middle


def _match_block_at(
    path_segs: list[str], start: int, exact: tuple[tuple[int, str], ...]
) -> bool:
    for off, lit in exact:
        if path_segs[start + off] != lit:
            return False
    return True


def _match_resource(
    path_segs: list[str],
    has_double: bool,
    min_len: int,
    arg1,
    arg2,
    arg3,
) -> bool:
    n = len(path_segs)
    if not has_double:
        if n != min_len:
            return False
        for idx, lit in arg1:
            if path_segs[idx] != lit:
                return False
        return True

    if n < min_len:
        return False

    p_len, p_exact = arg1
    if p_len and not _match_block_at(path_segs, 0, p_exact):
        return False

    s_len, s_exact = arg2
    limit = n - s_len
    if s_len and not _match_block_at(path_segs, limit, s_exact):
        return False

    cur = p_len
    for b_len, b_exact in arg3:
        for pos in range(cur, limit - b_len + 1):
            if not b_exact or _match_block_at(path_segs, pos, b_exact):
                cur = pos + b_len
                break
        else:
            return False

    return True


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    compiled_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")

        fields = rule.split()
        count = len(fields)
        if count != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {count}")

        effect, principal, action, resource = fields

        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        if principal == "*":
            p_type = 0
            p_val = ""
        elif principal.startswith("user:") and _NAME_RE.fullmatch(principal[5:]) is not None:
            p_type = 2
            p_val = principal[5:]
        elif principal.startswith("group:") and _NAME_RE.fullmatch(principal[6:]) is not None:
            p_type = 1
            p_val = principal[6:]
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")

        if action == "*":
            a_rank = 0
            a_set = None
        elif _ACTION_RE.fullmatch(action) is not None:
            a_rank = 1
            a_set = frozenset(action.split(","))
        else:
            raise ValueError(f"rule {i}: bad action {action!r}")

        if resource == "/":
            r_segs: list[str] = []
        elif resource.startswith("/"):
            r_segs = resource[1:].split("/")
            if not all(_SEG_PAT_RE.fullmatch(s) is not None for s in r_segs):
                raise ValueError(f"rule {i}: bad resource {resource!r}")
        else:
            raise ValueError(f"rule {i}: bad resource {resource!r}")

        L, has_double, min_len, arg1, arg2, arg3 = _compile_resource(r_segs)
        is_allow = 0 if effect == "DENY" else 1
        decision = f"{effect} by rule {i}"
        compiled_rules.append(
            (
                (-L, -p_type, -a_rank, is_allow, i),
                p_type,
                p_val,
                a_set,
                has_double,
                min_len,
                arg1,
                arg2,
                arg3,
                decision,
            )
        )

    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")

        user, groups, action, path = req

        if not isinstance(user, str) or _NAME_RE.fullmatch(user) is None:
            raise ValueError(f"request {j}: bad user {user!r}")

        if not isinstance(groups, list) or any(
            not isinstance(g, str) or _NAME_RE.fullmatch(g) is None for g in groups
        ):
            raise ValueError(f"request {j}: bad groups")

        if not isinstance(action, str) or _ACTION_WORD_RE.fullmatch(action) is None:
            raise ValueError(f"request {j}: bad action {action!r}")

        if not isinstance(path, str):
            raise ValueError(f"request {j}: bad path {path!r}")
        if path == "/":
            p_segs: list[str] = []
        elif path.startswith("/"):
            p_segs = path[1:].split("/")
            if not all(_PATH_SEG_RE.fullmatch(s) is not None for s in p_segs):
                raise ValueError(f"request {j}: bad path {path!r}")
        else:
            raise ValueError(f"request {j}: bad path {path!r}")

        parsed_requests.append((user, frozenset(groups), action, p_segs))

    # Sort by highest specificity first, then DENY before ALLOW, then smallest rule index.
    # The first matching rule in this order is guaranteed to be the final decision.
    compiled_rules.sort(key=lambda r: r[0])

    decisions: list[str] = []
    for user, group_set, action, p_segs in parsed_requests:
        result = "DENY by default"
        for (
            _,
            p_type,
            p_val,
            a_set,
            has_double,
            min_len,
            arg1,
            arg2,
            arg3,
            decision,
        ) in compiled_rules:
            if p_type == 2:
                if p_val != user:
                    continue
            elif p_type == 1:
                if p_val not in group_set:
                    continue

            if a_set is not None and action not in a_set:
                continue

            if _match_resource(p_segs, has_double, min_len, arg1, arg2, arg3):
                result = decision
                break

        decisions.append(result)

    return decisions

import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _json_type(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "str"
    if isinstance(value, list):
        return "list"
    if isinstance(value, dict):
        return "dict"
    return type(value).__name__


def _clone(value):
    if isinstance(value, dict):
        return {k: _clone(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_clone(item) for item in value]
    return value


def _child_path(parent_path: str, name: str) -> str:
    if _IDENT_RE.fullmatch(name):
        return f"{parent_path}.{name}"
    return f"{parent_path}[{json.dumps(name, ensure_ascii=False)}]"


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    def merge_into(overlay: dict, target: dict, path: str, layer_idx: int) -> None:
        for key, value in overlay.items():
            if not isinstance(key, str):
                raise TypeError(f"layer {layer_idx}: non-string key at {path}")

            if key.startswith("-"):
                op = "DELETE"
                name = key[1:]
            elif key.endswith("+"):
                op = "APPEND"
                name = key[:-1]
            else:
                op = "SET"
                name = key

            if name == "":
                raise ValueError(f"layer {layer_idx}: empty key name at {path}")

            child_path = _child_path(path, name)

            if op == "DELETE":
                if value is not None:
                    raise ValueError(
                        f"layer {layer_idx}: delete directive needs null at {child_path}"
                    )
                if name in target:
                    del target[name]
                else:
                    warnings.append(
                        f"layer {layer_idx}: delete of missing key at {child_path}"
                    )
            elif op == "APPEND":
                if not isinstance(value, list):
                    raise ValueError(
                        f"layer {layer_idx}: append directive needs a list at {child_path}"
                    )
                if name not in target:
                    target[name] = _clone(value)
                elif isinstance(target[name], list):
                    target[name].extend(_clone(item) for item in value)
                else:
                    raise ValueError(
                        f"layer {layer_idx}: cannot append to {_json_type(target[name])} at {child_path}"
                    )
            else:  # SET
                if name in target:
                    old_type = _json_type(target[name])
                    new_type = _json_type(value)
                    if old_type != new_type:
                        warnings.append(
                            f"layer {layer_idx}: type change at {child_path}: {old_type} -> {new_type}"
                        )

                if isinstance(value, dict):
                    if name not in target or not isinstance(target[name], dict):
                        target[name] = {}
                    merge_into(value, target[name], child_path, layer_idx)
                else:
                    target[name] = _clone(value)

    for layer_idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {layer_idx} is not a dict")
        merge_into(layer, result, "$", layer_idx)

    return result, warnings

from __future__ import annotations

import re
from collections.abc import Callable

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:~rc([1-9][0-9]*))?"
)
_AT_RE = re.compile(r"@(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)")
_MAJ_WILDCARD_RE = re.compile(r"(0|[1-9][0-9]*)\.\*")
_MIN_WILDCARD_RE = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.\*")

# (major, minor, patch, is_release, rc_num)
# Plain releases have (1, 0); release candidates have (0, N) so every RC < plain release.
_Version = tuple[int, int, int, int, int]


def _parse_version(s: str) -> _Version | None:
    m = _VERSION_RE.fullmatch(s)
    if m is None:
        return None
    x = int(m.group(1))
    y = int(m.group(2))
    z = int(m.group(3))
    rc = m.group(4)
    if rc is None:
        return (x, y, z, 1, 0)
    return (x, y, z, 0, int(rc))


def _parse_clause(clause: str) -> Callable[[_Version], bool] | None:
    if clause == "*":
        return lambda v: True

    m = _AT_RE.fullmatch(clause)
    if m is not None:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v: v[0] == x and v[1] >= y

    m = _MAJ_WILDCARD_RE.fullmatch(clause)
    if m is not None:
        x = int(m.group(1))
        return lambda v: v[0] == x

    m = _MIN_WILDCARD_RE.fullmatch(clause)
    if m is not None:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v: v[0] == x and v[1] == y

    if clause.startswith(">="):
        target = _parse_version(clause[2:])
        return (lambda v: v >= target) if target is not None else None
    if clause.startswith("<="):
        target = _parse_version(clause[2:])
        return (lambda v: v <= target) if target is not None else None
    if clause.startswith("!="):
        target = _parse_version(clause[2:])
        return (lambda v: v != target) if target is not None else None
    if clause.startswith(">"):
        target = _parse_version(clause[1:])
        return (lambda v: v > target) if target is not None else None
    if clause.startswith("<"):
        target = _parse_version(clause[1:])
        return (lambda v: v < target) if target is not None else None
    if clause.startswith("="):
        target = _parse_version(clause[1:])
        return (lambda v: v == target) if target is not None else None

    target = _parse_version(clause)
    if target is not None:
        return lambda v: v == target
    return None


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    parsed_available: list[tuple[_Version, str]] = []
    for i, element in enumerate(available):
        if not isinstance(element, str):
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed = _parse_version(element)
        if parsed is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append((parsed, element))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives: list[tuple[bool, list[Callable[[_Version], bool]]]] = []
    for a, raw_alt in enumerate(constraint.split("|"), 1):
        alt = raw_alt.strip(" ")
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        else:
            allow_rc = False
        if alt == "":
            raise ValueError(f"alternative {a} is empty")

        predicates: list[Callable[[_Version], bool]] = []
        for c, raw_clause in enumerate(alt.split(","), 1):
            clause = raw_clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            predicates.append(pred)
        alternatives.append((allow_rc, predicates))

    best_ver: _Version | None = None
    best_str: str | None = None

    for ver, ver_str in parsed_available:
        is_rc = ver[3] == 0
        for allow_rc, predicates in alternatives:
            if is_rc and not allow_rc:
                continue
            if all(pred(ver) for pred in predicates):
                if best_ver is None or ver > best_ver:
                    best_ver = ver
                    best_str = ver_str
                break

    return best_str

import re

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*\Z")
_INT_RE = re.compile(r"-?(?:0|[1-9][0-9]*)\Z")


def _parse_scalar(text: str):
    if text[0] == '"':
        if "\\" not in text:
            end = text.find('"', 1)
            if end != len(text) - 1:
                return None, "bad string"
            return text[1:-1], None

        out = []
        i = 1
        n = len(text)
        while i < n:
            ch = text[i]
            if ch == '"':
                if i != n - 1:
                    return None, "bad string"
                return "".join(out), None
            if ch == "\\":
                i += 1
                if i >= n:
                    return None, "bad escape"
                esc = text[i]
                if esc == "\\":
                    out.append("\\")
                elif esc == '"':
                    out.append('"')
                elif esc == "n":
                    out.append("\n")
                elif esc == "t":
                    out.append("\t")
                else:
                    return None, "bad escape"
                i += 1
            else:
                out.append(ch)
                i += 1
        return None, "bad string"

    if text == "true":
        return True, None
    if text == "false":
        return False, None
    if text == "null":
        return None, None
    if _INT_RE.match(text):
        return int(text), None
    return text, None


def parse_outline(text: str) -> tuple:
    stack = []  # entries: (indent, kind, container); kind: 0 = mapping, 1 = list
    root = None
    has_root = False
    pending = None  # None or (parent_container, key_or_index, opener_indent)

    for lineno, line in enumerate(text.split("\n"), 1):
        rest = line.lstrip(" \t")
        if not rest or rest[0] == "#":
            continue

        lead_len = len(line) - len(rest)
        if lead_len and "\t" in line[:lead_len]:
            return ("error", lineno, "tab in indentation")

        # Content line syntax
        if rest == "-" or rest.startswith("- "):
            line_kind = 1
            key = None
            raw = rest[2:].strip(" ")
            if raw == "":
                is_opener = True
                val = None
            else:
                is_opener = False
                val, err = _parse_scalar(raw)
                if err is not None:
                    return ("error", lineno, err)
        else:
            colon = rest.find(":")
            if colon == -1:
                return ("error", lineno, "invalid entry")
            key = rest[:colon]
            if not _KEY_RE.match(key):
                return ("error", lineno, "invalid entry")
            after = rest[colon + 1 :]
            stripped = after.strip(" ")
            if stripped == "":
                line_kind = 0
                is_opener = True
                val = None
            elif after[0] == " ":
                line_kind = 0
                is_opener = False
                val, err = _parse_scalar(stripped)
                if err is not None:
                    return ("error", lineno, err)
            else:
                return ("error", lineno, "invalid entry")

        # Structure checks
        if not has_root:
            if lead_len != 0:
                return ("error", lineno, "unexpected indent")
            has_root = True
            container = {} if line_kind == 0 else []
            root = container
            stack.append((0, line_kind, container))
            if line_kind == 0:
                container[key] = val
                pending = (container, key, 0) if is_opener else None
            else:
                container.append(val)
                pending = (container, 0, 0) if is_opener else None
        elif pending is not None and lead_len > pending[2]:
            parent_container, parent_ref, _ = pending
            container = {} if line_kind == 0 else []
            parent_container[parent_ref] = container
            stack.append((lead_len, line_kind, container))
            if line_kind == 0:
                container[key] = val
                pending = (container, key, lead_len) if is_opener else None
            else:
                container.append(val)
                pending = (container, 0, lead_len) if is_opener else None
        else:
            pending = None
            top_indent = stack[-1][0]
            if lead_len > top_indent:
                return ("error", lineno, "unexpected indent")
            if lead_len < top_indent:
                while stack and stack[-1][0] > lead_len:
                    stack.pop()
                if not stack or stack[-1][0] != lead_len:
                    return ("error", lineno, "inconsistent dedent")

            _, b_kind, container = stack[-1]
            if line_kind != b_kind:
                return ("error", lineno, "mixed block")
            if line_kind == 0:
                if key in container:
                    return ("error", lineno, f"duplicate key '{key}'")
                container[key] = val
                if is_opener:
                    pending = (container, key, lead_len)
            else:
                container.append(val)
                if is_opener:
                    pending = (container, len(container) - 1, lead_len)

    if not has_root:
        return ("ok", None)
    return ("ok", root)

import re

_TOKEN_RE = re.compile(r'\[|\]|[^ \t\n\r\[\]]+')
_INT_RE = re.compile(r'-?[0-9]+\Z')

_OP_INT = 0
_OP_QUOT = 1
_OP_DEF = 2
_OP_WORD = 3
_OP_DUP = 4
_OP_DROP = 5
_OP_SWAP = 6
_OP_OVER = 7
_OP_ROT = 8
_OP_ADD = 9
_OP_SUB = 10
_OP_MUL = 11
_OP_DIV = 12
_OP_MOD = 13
_OP_LT = 14
_OP_EQ = 15
_OP_IF = 16
_OP_TIMES = 17
_OP_WHILE = 18
_OP_CALL = 19
_OP_DIP = 20

_BUILTIN_OP = {
    "dup": _OP_DUP,
    "drop": _OP_DROP,
    "swap": _OP_SWAP,
    "over": _OP_OVER,
    "rot": _OP_ROT,
    "+": _OP_ADD,
    "-": _OP_SUB,
    "*": _OP_MUL,
    "/": _OP_DIV,
    "%": _OP_MOD,
    "<": _OP_LT,
    "=": _OP_EQ,
    "if": _OP_IF,
    "times": _OP_TIMES,
    "while": _OP_WHILE,
    "call": _OP_CALL,
    "dip": _OP_DIP,
}

_BAD_NAMES = frozenset(("[", "]", ":", ";")) | frozenset(_BUILTIN_OP)

_KIND_RET = 0
_KIND_DIP = 1
_KIND_TIMES = 2
_KIND_WHILE_C = 3
_KIND_WHILE_B = 4


class _Quot:
    __slots__ = ("code", "formatted")

    def __init__(self, code: tuple):
        self.code = code
        self.formatted = None


def _parse_int(s: str) -> int:
    try:
        return int(s)
    except ValueError:
        neg = s[0] == "-"
        if neg:
            s = s[1:]
        res = 0
        for i in range(0, len(s), 1000):
            chunk = s[i:i + 1000]
            res = res * (10 ** len(chunk)) + int(chunk)
        return -res if neg else res


def _format_quot(root_q: _Quot, tokens: list) -> list:
    if root_q.formatted is not None:
        return root_q.formatted
    op_quot = _OP_QUOT
    work = [[root_q, 0, []]]
    while work:
        frame = work[-1]
        q = frame[0]
        idx = frame[1]
        code = q.code
        if idx < len(code):
            instr = code[idx]
            frame[1] = idx + 1
            if instr[0] == op_quot:
                child = instr[2]
                if child.formatted is not None:
                    frame[2].append(child.formatted)
                else:
                    work.append([child, 0, []])
            else:
                frame[2].append(tokens[instr[1]])
        else:
            q.formatted = frame[2]
            work.pop()
            if work:
                work[-1][2].append(q.formatted)
    return root_q.formatted


def run_pile(src: str, max_steps: int) -> tuple:
    tokens = _TOKEN_RE.findall(src)
    n_tokens = len(tokens)

    # Pass 1: structure check
    open_stack = []
    i = 0
    while i < n_tokens:
        tok = tokens[i]
        if tok == "[":
            open_stack.append(("[", i))
            i += 1
        elif tok == "]":
            if not open_stack or open_stack[-1][0] != "[":
                return ("error", i, "unmatched ]")
            open_stack.pop()
            i += 1
        elif tok == ":":
            if open_stack:
                return ("error", i, "misplaced :")
            if i + 1 >= n_tokens:
                return ("error", i, "unclosed :")
            name = tokens[i + 1]
            if name in _BAD_NAMES or _INT_RE.match(name):
                return ("error", i + 1, "bad name")
            open_stack.append((":", i))
            i += 2
        elif tok == ";":
            if not open_stack or open_stack[-1][0] != ":":
                return ("error", i, "unmatched ;")
            open_stack.pop()
            i += 1
        else:
            i += 1

    if open_stack:
        kind, idx = open_stack[0]
        return ("error", idx, "unclosed [" if kind == "[" else "unclosed :")

    # Pass 2: compile iteratively
    op_int = _OP_INT
    op_quot = _OP_QUOT
    op_def = _OP_DEF
    op_word = _OP_WORD
    builtin_op = _BUILTIN_OP
    int_re = _INT_RE

    seq_stack = [[]]
    meta_stack = []
    i = 0
    while i < n_tokens:
        tok = tokens[i]
        if tok == "[":
            seq_stack.append([])
            meta_stack.append(i)
            i += 1
        elif tok == "]":
            body = tuple(seq_stack.pop())
            open_idx = meta_stack.pop()
            seq_stack[-1].append((op_quot, open_idx, _Quot(body)))
            i += 1
        elif tok == ":":
            seq_stack.append([])
            meta_stack.append((i, tokens[i + 1]))
            i += 2
        elif tok == ";":
            body = tuple(seq_stack.pop())
            colon_idx, name = meta_stack.pop()
            seq_stack[-1].append((op_def, colon_idx, name, body))
            i += 1
        else:
            b_op = builtin_op.get(tok)
            if b_op is not None:
                seq_stack[-1].append((b_op, i))
            elif int_re.match(tok):
                seq_stack[-1].append((op_int, i, _parse_int(tok)))
            else:
                seq_stack[-1].append((op_word, i, tok))
            i += 1

    # Pass 3: execute iteratively
    op_dup = _OP_DUP
    op_drop = _OP_DROP
    op_swap = _OP_SWAP
    op_over = _OP_OVER
    op_rot = _OP_ROT
    op_add = _OP_ADD
    op_sub = _OP_SUB
    op_mul = _OP_MUL
    op_div = _OP_DIV
    op_mod = _OP_MOD
    op_lt = _OP_LT
    op_eq = _OP_EQ
    op_if = _OP_IF
    op_times = _OP_TIMES
    op_while = _OP_WHILE
    op_call = _OP_CALL
    op_dip = _OP_DIP

    kind_ret = _KIND_RET
    kind_dip = _KIND_DIP
    kind_times = _KIND_TIMES
    kind_while_c = _KIND_WHILE_C
    kind_while_b = _KIND_WHILE_B
    Quot = _Quot

    stack = []
    defs = {}
    frames = []
    code = tuple(seq_stack[0])
    pc = 0
    code_len = len(code)
    steps = 0

    while True:
        while pc >= code_len:
            if not frames:
                out = [
                    x if type(x) is int else _format_quot(x, tokens)
                    for x in stack
                ]
                return ("ok", out)
            top = frames[-1]
            kind = top[0]
            if kind == kind_ret:
                frames.pop()
                code = top[1]
                pc = top[2]
                code_len = len(code)
            elif kind == kind_dip:
                frames.pop()
                stack.append(top[1])
                code = top[2]
                pc = top[3]
                code_len = len(code)
            elif kind == kind_times:
                rem = top[2] - 1
                if rem > 0:
                    top[2] = rem
                    code = top[1]
                    pc = 0
                    code_len = len(code)
                else:
                    frames.pop()
                    code = top[3]
                    pc = top[4]
                    code_len = len(code)
            elif kind == kind_while_c:
                if not stack:
                    return ("error", top[3], "stack underflow")
                v = stack.pop()
                if type(v) is not int:
                    return ("error", top[3], "type error")
                if v == 0:
                    frames.pop()
                    code = top[4]
                    pc = top[5]
                    code_len = len(code)
                else:
                    b_code = top[2]
                    if b_code:
                        top[0] = kind_while_b
                        code = b_code
                        pc = 0
                        code_len = len(b_code)
                    else:
                        code = top[1]
                        pc = 0
                        code_len = len(code)
            else:  # kind_while_b
                top[0] = kind_while_c
                code = top[1]
                pc = 0
                code_len = len(code)

        instr = code[pc]
        if steps >= max_steps:
            return ("error", instr[1], "step limit exceeded")
        steps += 1
        pc += 1
        op = instr[0]

        if op == op_int:
            stack.append(instr[2])
        elif op == op_quot:
            stack.append(instr[2])
        elif op == op_word:
            name = instr[2]
            body = defs.get(name)
            if body is None:
                return ("error", instr[1], f"unknown word '{name}'")
            if body:
                if pc < code_len:
                    frames.append((kind_ret, code, pc))
                code = body
                pc = 0
                code_len = len(body)
        elif op == op_dup:
            if not stack:
                return ("error", instr[1], "stack underflow")
            stack.append(stack[-1])
        elif op == op_drop:
            if not stack:
                return ("error", instr[1], "stack underflow")
            stack.pop()
        elif op == op_swap:
            if len(stack) < 2:
                return ("error", instr[1], "stack underflow")
            stack[-2], stack[-1] = stack[-1], stack[-2]
        elif op == op_over:
            if len(stack) < 2:
                return ("error", instr[1], "stack underflow")
            stack.append(stack[-2])
        elif op == op_rot:
            if len(stack) < 3:
                return ("error", instr[1], "stack underflow")
            stack[-3], stack[-2], stack[-1] = stack[-2], stack[-1], stack[-3]
        elif op <= op_eq:
            if len(stack) < 2:
                return ("error", instr[1], "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", instr[1], "type error")
            if op == op_add:
                stack.pop()
                stack[-1] = a + b
            elif op == op_sub:
                stack.pop()
                stack[-1] = a - b
            elif op == op_mul:
                stack.pop()
                stack[-1] = a * b
            elif op == op_div:
                if b == 0:
                    return ("error", instr[1], "division by zero")
                stack.pop()
                stack[-1] = a // b
            elif op == op_mod:
                if b == 0:
                    return ("error", instr[1], "division by zero")
                stack.pop()
                stack[-1] = a % b
            elif op == op_lt:
                stack.pop()
                stack[-1] = 1 if a < b else 0
            else:  # op_eq
                stack.pop()
                stack[-1] = 1 if a == b else 0
        elif op == op_if:
            if len(stack) < 3:
                return ("error", instr[1], "stack underflow")
            f = stack[-1]
            t = stack[-2]
            c = stack[-3]
            if type(c) is not int or type(t) is not Quot or type(f) is not Quot:
                return ("error", instr[1], "type error")
            del stack[-3:]
            target = t.code if c != 0 else f.code
            if target:
                if pc < code_len:
                    frames.append((kind_ret, code, pc))
                code = target
                pc = 0
                code_len = len(target)
        elif op == op_call:
            if not stack:
                return ("error", instr[1], "stack underflow")
            q = stack[-1]
            if type(q) is not Quot:
                return ("error", instr[1], "type error")
            stack.pop()
            target = q.code
            if target:
                if pc < code_len:
                    frames.append((kind_ret, code, pc))
                code = target
                pc = 0
                code_len = len(target)
        elif op == op_dip:
            if len(stack) < 2:
                return ("error", instr[1], "stack underflow")
            q = stack[-1]
            if type(q) is not Quot:
                return ("error", instr[1], "type error")
            stack.pop()
            a = stack.pop()
            q_code = q.code
            if q_code:
                frames.append((kind_dip, a, code, pc))
                code = q_code
                pc = 0
                code_len = len(q_code)
            else:
                stack.append(a)
        elif op == op_times:
            if len(stack) < 2:
                return ("error", instr[1], "stack underflow")
            n = stack[-1]
            q = stack[-2]
            if type(q) is not Quot or type(n) is not int:
                return ("error", instr[1], "type error")
            if n < 0:
                return ("error", instr[1], "negative count")
            del stack[-2:]
            q_code = q.code
            if n > 0 and q_code:
                frames.append([kind_times, q_code, n, code, pc])
                code = q_code
                pc = 0
                code_len = len(q_code)
        elif op == op_while:
            if len(stack) < 2:
                return ("error", instr[1], "stack underflow")
            b = stack[-1]
            c = stack[-2]
            if type(c) is not Quot or type(b) is not Quot:
                return ("error", instr[1], "type error")
            del stack[-2:]
            c_code = c.code
            frames.append([kind_while_c, c_code, b.code, instr[1], code, pc])
            code = c_code
            pc = 0
            code_len = len(c_code)
        else:  # op_def
            defs[instr[2]] = instr[3]

_MISSING = object()

_T_LPAREN = 0
_T_RPAREN = 1
_T_LBRACK = 2
_T_RBRACK = 3
_T_COMMA = 4
_T_OP = 5
_T_INT = 6
_T_STR = 7
_T_AND = 8
_T_OR = 9
_T_NOT = 10
_T_IN = 11
_T_HAS = 12
_T_FIELD = 13
_T_END = 14

_KEYWORDS = {
    "and": _T_AND,
    "or": _T_OR,
    "not": _T_NOT,
    "in": _T_IN,
    "has": _T_HAS,
}

_OP_HAS = 0
_OP_EQ = 1
_OP_NE = 2
_OP_LT = 3
_OP_LE = 4
_OP_GT = 5
_OP_GE = 6
_OP_IN = 7
_OP_NOT = 8
_OP_MIN = 9
_OP_MAX = 10
_OP_JIF = 11
_OP_JIT = 12

_CMP_MAP = {
    "=": _OP_EQ,
    "!=": _OP_NE,
    "<": _OP_LT,
    "<=": _OP_LE,
    ">": _OP_GT,
    ">=": _OP_GE,
}


def _parse_int(s: str) -> int:
    if len(s) <= 4000:
        return int(s)
    neg = s[0] == "-"
    digits = s[1:] if neg else s

    def _conv(d: str) -> int:
        if len(d) <= 2000:
            return int(d)
        mid = len(d) >> 1
        return _conv(d[:mid]) * (10 ** (len(d) - mid)) + _conv(d[mid:])

    val = _conv(digits)
    return -val if neg else val


def _tok_error(tok: tuple) -> tuple:
    kind, pos, raw, _ = tok
    if kind == _T_END:
        return ("error", pos, "unexpected end of input")
    return ("error", pos, f"unexpected token '{raw}'")


def filter_records(query: str, records: list[dict]) -> tuple:
    # STEP 1: LEXING
    n = len(query)
    tokens = []
    i = 0
    while i < n:
        c = query[i]
        if c == " " or c == "\t" or c == "\n":
            i += 1
        elif c == "(":
            tokens.append((_T_LPAREN, i, "(", None))
            i += 1
        elif c == ")":
            tokens.append((_T_RPAREN, i, ")", None))
            i += 1
        elif c == "[":
            tokens.append((_T_LBRACK, i, "[", None))
            i += 1
        elif c == "]":
            tokens.append((_T_RBRACK, i, "]", None))
            i += 1
        elif c == ",":
            tokens.append((_T_COMMA, i, ",", None))
            i += 1
        elif c == "=":
            tokens.append((_T_OP, i, "=", None))
            i += 1
        elif c == "<" or c == ">":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_T_OP, i, query[i : i + 2], None))
                i += 2
            else:
                tokens.append((_T_OP, i, c, None))
                i += 1
        elif c == "!":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_T_OP, i, "!=", None))
                i += 2
            else:
                return ("error", i, "unexpected character '!'")
        elif c == "-" or ("0" <= c <= "9"):
            start = i
            if c == "-":
                if i + 1 >= n or not ("0" <= query[i + 1] <= "9"):
                    return ("error", i, "unexpected character '-'")
                i += 2
            else:
                i += 1
            while i < n and "0" <= query[i] <= "9":
                i += 1
            tokens.append((_T_INT, start, query[start:i], None))
        elif c == '"':
            start = i
            i += 1
            parts = []
            seg_start = i
            closed = False
            while i < n:
                ch = query[i]
                if ch == '"':
                    parts.append(query[seg_start:i])
                    i += 1
                    closed = True
                    break
                elif ch == "\\":
                    parts.append(query[seg_start:i])
                    if i + 1 >= n:
                        return ("error", i, "bad escape")
                    nxt = query[i + 1]
                    if nxt != '"' and nxt != "\\":
                        return ("error", i, "bad escape")
                    parts.append(nxt)
                    i += 2
                    seg_start = i
                else:
                    i += 1
            if not closed:
                return ("error", start, "unterminated string")
            val = "".join(parts) if len(parts) > 1 else parts[0]
            tokens.append((_T_STR, start, query[start:i], val))
        elif ("A" <= c <= "Z") or ("a" <= c <= "z") or c == "_":
            start = i
            i += 1
            while i < n:
                ch = query[i]
                if (
                    ("A" <= ch <= "Z")
                    or ("a" <= ch <= "z")
                    or ("0" <= ch <= "9")
                    or ch == "_"
                    or ch == "."
                ):
                    i += 1
                else:
                    break
            word = query[start:i]
            kw = _KEYWORDS.get(word)
            if kw is not None:
                tokens.append((kw, start, word, None))
            else:
                tokens.append((_T_FIELD, start, word, None))
        else:
            return ("error", i, f"unexpected character '{c}'")

    tokens.append((_T_END, n, "", None))

    # STEP 2: ITERATIVE PARSING
    frames = [[0, [], []]]  # [not_count, or_terms, and_terms]
    ti = 0
    expect_expr = True
    cur_node = None

    while True:
        tok = tokens[ti]
        kind = tok[0]
        if expect_expr:
            if kind == _T_NOT:
                frames[-1][0] += 1
                ti += 1
            elif kind == _T_LPAREN:
                frames.append([0, [], []])
                ti += 1
            elif kind == _T_HAS:
                ti += 1
                ntok = tokens[ti]
                if ntok[0] != _T_FIELD:
                    return _tok_error(ntok)
                ti += 1
                cur_node = ("HAS", ntok[2])
                if frames[-1][0] & 1:
                    cur_node = ("NOT", cur_node)
                frames[-1][0] = 0
                expect_expr = False
            elif kind == _T_FIELD:
                field = tok[2]
                ti += 1
                ntok = tokens[ti]
                nkind = ntok[0]
                if nkind == _T_OP:
                    op = ntok[2]
                    ti += 1
                    ltok = tokens[ti]
                    lkind = ltok[0]
                    if lkind == _T_INT:
                        val = _parse_int(ltok[2])
                    elif lkind == _T_STR:
                        val = ltok[3]
                    else:
                        return _tok_error(ltok)
                    ti += 1
                    cur_node = ("CMP", field, op, val)
                elif nkind == _T_IN:
                    ti += 1
                    btok = tokens[ti]
                    if btok[0] != _T_LBRACK:
                        return _tok_error(btok)
                    ti += 1
                    lits = []
                    while True:
                        ltok = tokens[ti]
                        lkind = ltok[0]
                        if lkind == _T_INT:
                            lits.append(_parse_int(ltok[2]))
                        elif lkind == _T_STR:
                            lits.append(ltok[3])
                        else:
                            return _tok_error(ltok)
                        ti += 1
                        ctok = tokens[ti]
                        if ctok[0] == _T_COMMA:
                            ti += 1
                        else:
                            break
                    etok = tokens[ti]
                    if etok[0] != _T_RBRACK:
                        return _tok_error(etok)
                    ti += 1
                    cur_node = ("IN", field, frozenset(lits))
                else:
                    return _tok_error(ntok)
                if frames[-1][0] & 1:
                    cur_node = ("NOT", cur_node)
                frames[-1][0] = 0
                expect_expr = False
            else:
                return _tok_error(tok)
        else:
            if kind == _T_AND:
                frames[-1][2].append(cur_node)
                ti += 1
                expect_expr = True
            elif kind == _T_OR:
                frame = frames[-1]
                and_terms = frame[2]
                if and_terms:
                    and_terms.append(cur_node)
                    term = ("AND", and_terms)
                    frame[2] = []
                else:
                    term = cur_node
                frame[1].append(term)
                ti += 1
                expect_expr = True
            elif kind == _T_RPAREN:
                if len(frames) == 1:
                    return _tok_error(tok)
                frame = frames.pop()
                and_terms = frame[2]
                if and_terms:
                    and_terms.append(cur_node)
                    term = ("AND", and_terms)
                else:
                    term = cur_node
                or_terms = frame[1]
                if or_terms:
                    or_terms.append(term)
                    cur_node = ("OR", or_terms)
                else:
                    cur_node = term
                if frames[-1][0] & 1:
                    if cur_node[0] == "NOT":
                        cur_node = cur_node[1]
                    else:
                        cur_node = ("NOT", cur_node)
                frames[-1][0] = 0
                ti += 1
            elif kind == _T_END:
                if len(frames) > 1:
                    return _tok_error(tok)
                frame = frames[0]
                and_terms = frame[2]
                if and_terms:
                    and_terms.append(cur_node)
                    term = ("AND", and_terms)
                else:
                    term = cur_node
                or_terms = frame[1]
                if or_terms:
                    or_terms.append(term)
                    root = ("OR", or_terms)
                else:
                    root = term
                break
            else:
                return _tok_error(tok)

    # COMPILE AST TO FLAT BYTECODE ITERATIVELY
    code = []
    todo = [("C", root)]
    while todo:
        item = todo.pop()
        tag = item[0]
        if tag == "C":
            node = item[1]
            nkind = node[0]
            if nkind == "HAS":
                code.append((_OP_HAS, node[1]))
            elif nkind == "CMP":
                code.append((_CMP_MAP[node[2]], node[1], node[3], type(node[3])))
            elif nkind == "IN":
                code.append((_OP_IN, node[1], node[2]))
            elif nkind == "NOT":
                todo.append(("E", (_OP_NOT,)))
                todo.append(("C", node[1]))
            elif nkind == "AND":
                children = node[1]
                jumps = []
                todo.append(("P", jumps))
                last = len(children) - 1
                for j in range(last, -1, -1):
                    if j > 0:
                        if j < last:
                            todo.append(("J", _OP_JIF, jumps))
                        todo.append(("E", (_OP_MIN,)))
                        todo.append(("C", children[j]))
                    else:
                        todo.append(("J", _OP_JIF, jumps))
                        todo.append(("C", children[0]))
            elif nkind == "OR":
                children = node[1]
                jumps = []
                todo.append(("P", jumps))
                last = len(children) - 1
                for j in range(last, -1, -1):
                    if j > 0:
                        if j < last:
                            todo.append(("J", _OP_JIT, jumps))
                        todo.append(("E", (_OP_MAX,)))
                        todo.append(("C", children[j]))
                    else:
                        todo.append(("J", _OP_JIT, jumps))
                        todo.append(("C", children[0]))
        elif tag == "E":
            code.append(item[1])
        elif tag == "J":
            item[2].append(len(code))
            code.append([item[1], -1])
        elif tag == "P":
            target = len(code)
            for jidx in item[1]:
                code[jidx] = (code[jidx][0], target)

    # STEP 3: ITERATIVE EVALUATION (FALSE = -1, UNKNOWN = 0, TRUE = 1)
    n_code = len(code)
    result = []
    missing = _MISSING
    for idx, rec in enumerate(records):
        stack = []
        pc = 0
        while pc < n_code:
            instr = code[pc]
            op = instr[0]
            if op == _OP_HAS:
                stack.append(1 if instr[1] in rec else -1)
            elif op == _OP_EQ:
                v = rec.get(instr[1], missing)
                if v is missing:
                    stack.append(0)
                elif type(v) is instr[3]:
                    stack.append(1 if v == instr[2] else -1)
                else:
                    stack.append(-1)
            elif op == _OP_NE:
                v = rec.get(instr[1], missing)
                if v is missing:
                    stack.append(0)
                elif type(v) is instr[3]:
                    stack.append(1 if v != instr[2] else -1)
                else:
                    stack.append(1)
            elif op == _OP_LT:
                v = rec.get(instr[1], missing)
                if v is missing or type(v) is not instr[3]:
                    stack.append(0)
                else:
                    stack.append(1 if v < instr[2] else -1)
            elif op == _OP_LE:
                v = rec.get(instr[1], missing)
                if v is missing or type(v) is not instr[3]:
                    stack.append(0)
                else:
                    stack.append(1 if v <= instr[2] else -1)
            elif op == _OP_GT:
                v = rec.get(instr[1], missing)
                if v is missing or type(v) is not instr[3]:
                    stack.append(0)
                else:
                    stack.append(1 if v > instr[2] else -1)
            elif op == _OP_GE:
                v = rec.get(instr[1], missing)
                if v is missing or type(v) is not instr[3]:
                    stack.append(0)
                else:
                    stack.append(1 if v >= instr[2] else -1)
            elif op == _OP_IN:
                v = rec.get(instr[1], missing)
                if v is missing:
                    stack.append(0)
                else:
                    stack.append(1 if v in instr[2] else -1)
            elif op == _OP_NOT:
                stack[-1] = -stack[-1]
            elif op == _OP_MIN:
                b = stack.pop()
                if b < stack[-1]:
                    stack[-1] = b
            elif op == _OP_MAX:
                b = stack.pop()
                if b > stack[-1]:
                    stack[-1] = b
            elif op == _OP_JIF:
                if stack[-1] == -1:
                    pc = instr[1]
                    continue
            else:  # _OP_JIT
                if stack[-1] == 1:
                    pc = instr[1]
                    continue
            pc += 1
        if stack[0] == 1:
            result.append(idx)

    return ("ok", result)

import re

_TOKEN_RE = re.compile(
    r"( +)|([0-9]+)|([a-z_][a-z0-9_]*)|(<=|>=|==|!=|[+\-*/%^()?:<>])|(.)",
    re.DOTALL,
)

# Token kinds (matching regex group indices, plus END)
_TOK_END = 0
_TOK_INT = 2
_TOK_NAME = 3
_TOK_OP = 4
_TOK_INVALID = 5

# Parser states (ordered from lowest to highest precedence)
_S_COND = 0
_S_CMP = 1
_S_SUM = 2
_S_TERM = 3
_S_UNARY = 4
_S_POWER = 5
_S_ATOM = 6
_S_DONE = 7

# Parser continuation tags
_K_COND_AFTER_CMP = 10
_K_CMP_AFTER_SUM = 11
_K_SUM_AFTER_TERM = 12
_K_TERM_AFTER_UNARY = 13
_K_POWER_AFTER_ATOM = 14
_K_EMIT_NEG = 15
_K_EXPECT_RPAREN = 16
_K_EXPECT_END = 17
_K_EMIT_BINOP = 18
_K_COND_AFTER_TRUE = 19
_K_COND_AFTER_FALSE = 20

# Bytecode opcodes
_OP_CONST = 0
_OP_CONST_STR = 1
_OP_LOAD = 2
_OP_NEG = 3
_OP_ADD = 4
_OP_SUB = 5
_OP_MUL = 6
_OP_DIV = 7
_OP_MOD = 8
_OP_POW = 9
_OP_LT = 10
_OP_LE = 11
_OP_GT = 12
_OP_GE = 13
_OP_EQ = 14
_OP_NE = 15
_OP_JZ = 16
_OP_JMP = 17

_BINOP_MAP = {
    "+": _OP_ADD,
    "-": _OP_SUB,
    "*": _OP_MUL,
    "/": _OP_DIV,
    "%": _OP_MOD,
    "^": _OP_POW,
    "<": _OP_LT,
    "<=": _OP_LE,
    ">": _OP_GT,
    ">=": _OP_GE,
    "==": _OP_EQ,
    "!=": _OP_NE,
}

_CMP_OPS = ("<", "<=", ">", ">=", "==", "!=")
_SUM_OPS = ("+", "-")
_TERM_OPS = ("*", "/", "%")


def _str_to_int(s: str) -> int:
    n = len(s)
    if n <= 500:
        return int(s)
    chunk_size = 500
    chunks = [int(s[max(0, i - chunk_size):i]) for i in range(n, 0, -chunk_size)]
    base = 10 ** chunk_size
    while len(chunks) > 1:
        next_chunks = []
        limit = len(chunks) - 1
        for i in range(0, limit, 2):
            next_chunks.append(chunks[i] + chunks[i + 1] * base)
        if len(chunks) & 1:
            next_chunks.append(chunks[-1])
        chunks = next_chunks
        if len(chunks) == 1:
            break
        base *= base
    return chunks[0]


def _syntax_error(tok_kind: int, tok_val: str, tok_pos: int) -> tuple:
    if tok_kind == _TOK_END:
        return ("error", tok_pos, "unexpected end of input")
    if tok_kind == _TOK_INVALID:
        return ("error", tok_pos, f"unexpected character '{tok_val}'")
    return ("error", tok_pos, f"unexpected token '{tok_val}'")


def evaluate(src: str, env: dict) -> tuple:
    len_src = len(src)
    it = _TOKEN_RE.finditer(src)

    def next_token() -> tuple:
        while True:
            m = next(it, None)
            if m is None:
                return _TOK_END, "", len_src
            kind = m.lastindex
            if kind != 1:
                return kind, m.group(kind), m.start()

    tok_kind, tok_val, tok_pos = next_token()
    code = []
    stack = [_K_EXPECT_END]
    state = _S_COND

    # Iterative LL(1) parser & bytecode compiler
    while True:
        if state <= _S_COND:
            stack.append(_K_COND_AFTER_CMP)
        if state <= _S_CMP:
            stack.append(_K_CMP_AFTER_SUM)
        if state <= _S_SUM:
            stack.append(_K_SUM_AFTER_TERM)
        if state <= _S_TERM:
            stack.append(_K_TERM_AFTER_UNARY)
        if state <= _S_UNARY:
            neg_parity = 0
            while tok_kind == _TOK_OP and tok_val == "-":
                neg_parity ^= 1
                tok_kind, tok_val, tok_pos = next_token()
            if neg_parity:
                stack.append(_K_EMIT_NEG)
        if state <= _S_POWER:
            stack.append(_K_POWER_AFTER_ATOM)

        # _S_ATOM
        if tok_kind == _TOK_INT:
            if len(tok_val) <= 500:
                code.append((_OP_CONST, int(tok_val)))
            else:
                code.append((_OP_CONST_STR, tok_val))
            tok_kind, tok_val, tok_pos = next_token()
        elif tok_kind == _TOK_NAME:
            code.append((_OP_LOAD, tok_val, tok_pos))
            tok_kind, tok_val, tok_pos = next_token()
        elif tok_kind == _TOK_OP and tok_val == "(":
            tok_kind, tok_val, tok_pos = next_token()
            stack.append(_K_EXPECT_RPAREN)
            state = _S_COND
            continue
        else:
            return _syntax_error(tok_kind, tok_val, tok_pos)

        # Pop continuations until descending again or finishing
        while True:
            item = stack.pop()
            if type(item) is int:
                if item == _K_POWER_AFTER_ATOM:
                    if tok_kind == _TOK_OP and tok_val == "^":
                        pos = tok_pos
                        tok_kind, tok_val, tok_pos = next_token()
                        stack.append((_K_EMIT_BINOP, _OP_POW, pos))
                        state = _S_UNARY
                        break
                elif item == _K_EMIT_NEG:
                    code.append((_OP_NEG,))
                elif item == _K_TERM_AFTER_UNARY:
                    if tok_kind == _TOK_OP and tok_val in _TERM_OPS:
                        op = _BINOP_MAP[tok_val]
                        pos = tok_pos
                        tok_kind, tok_val, tok_pos = next_token()
                        stack.append(_K_TERM_AFTER_UNARY)
                        stack.append((_K_EMIT_BINOP, op, pos))
                        state = _S_UNARY
                        break
                elif item == _K_SUM_AFTER_TERM:
                    if tok_kind == _TOK_OP and tok_val in _SUM_OPS:
                        op = _BINOP_MAP[tok_val]
                        pos = tok_pos
                        tok_kind, tok_val, tok_pos = next_token()
                        stack.append(_K_SUM_AFTER_TERM)
                        stack.append((_K_EMIT_BINOP, op, pos))
                        state = _S_TERM
                        break
                elif item == _K_CMP_AFTER_SUM:
                    if tok_kind == _TOK_OP and tok_val in _CMP_OPS:
                        op = _BINOP_MAP[tok_val]
                        pos = tok_pos
                        tok_kind, tok_val, tok_pos = next_token()
                        stack.append((_K_EMIT_BINOP, op, pos))
                        state = _S_SUM
                        break
                elif item == _K_COND_AFTER_CMP:
                    if tok_kind == _TOK_OP and tok_val == "?":
                        tok_kind, tok_val, tok_pos = next_token()
                        jz_idx = len(code)
                        code.append((_OP_JZ, 0))
                        stack.append((_K_COND_AFTER_TRUE, jz_idx))
                        state = _S_COND
                        break
                elif item == _K_EXPECT_RPAREN:
                    if tok_kind == _TOK_OP and tok_val == ")":
                        tok_kind, tok_val, tok_pos = next_token()
                    else:
                        return _syntax_error(tok_kind, tok_val, tok_pos)
                elif item == _K_EXPECT_END:
                    if tok_kind == _TOK_END:
                        state = _S_DONE
                        break
                    return _syntax_error(tok_kind, tok_val, tok_pos)
            else:
                tag = item[0]
                if tag == _K_EMIT_BINOP:
                    code.append((item[1], item[2]))
                elif tag == _K_COND_AFTER_TRUE:
                    if tok_kind == _TOK_OP and tok_val == ":":
                        tok_kind, tok_val, tok_pos = next_token()
                        jmp_idx = len(code)
                        code.append((_OP_JMP, 0))
                        code[item[1]] = (_OP_JZ, len(code))
                        stack.append((_K_COND_AFTER_FALSE, jmp_idx))
                        state = _S_COND
                        break
                    return _syntax_error(tok_kind, tok_val, tok_pos)
                elif tag == _K_COND_AFTER_FALSE:
                    code[item[1]] = (_OP_JMP, len(code))

        if state == _S_DONE:
            break

    # Iterative bytecode evaluation
    val_stack = []
    ip = 0
    n_code = len(code)
    while ip < n_code:
        instr = code[ip]
        op = instr[0]
        ip += 1
        if op == _OP_CONST:
            val_stack.append(instr[1])
        elif op == _OP_CONST_STR:
            val_stack.append(_str_to_int(instr[1]))
        elif op == _OP_LOAD:
            name = instr[1]
            if name not in env:
                return ("error", instr[2], f"unknown name '{name}'")
            val_stack.append(env[name])
        elif op == _OP_NEG:
            val_stack[-1] = -val_stack[-1]
        elif op == _OP_ADD:
            r = val_stack.pop()
            val_stack[-1] += r
        elif op == _OP_SUB:
            r = val_stack.pop()
            val_stack[-1] -= r
        elif op == _OP_MUL:
            r = val_stack.pop()
            val_stack[-1] *= r
        elif op == _OP_DIV:
            r = val_stack.pop()
            if r == 0:
                return ("error", instr[1], "division by zero")
            val_stack[-1] //= r
        elif op == _OP_MOD:
            r = val_stack.pop()
            if r == 0:
                return ("error", instr[1], "division by zero")
            val_stack[-1] %= r
        elif op == _OP_POW:
            r = val_stack.pop()
            if r < 0:
                return ("error", instr[1], "negative exponent")
            if r > 256:
                return ("error", instr[1], "exponent too large")
            val_stack[-1] **= r
        elif op == _OP_LT:
            r = val_stack.pop()
            val_stack[-1] = 1 if val_stack[-1] < r else 0
        elif op == _OP_LE:
            r = val_stack.pop()
            val_stack[-1] = 1 if val_stack[-1] <= r else 0
        elif op == _OP_GT:
            r = val_stack.pop()
            val_stack[-1] = 1 if val_stack[-1] > r else 0
        elif op == _OP_GE:
            r = val_stack.pop()
            val_stack[-1] = 1 if val_stack[-1] >= r else 0
        elif op == _OP_EQ:
            r = val_stack.pop()
            val_stack[-1] = 1 if val_stack[-1] == r else 0
        elif op == _OP_NE:
            r = val_stack.pop()
            val_stack[-1] = 1 if val_stack[-1] != r else 0
        elif op == _OP_JZ:
            if val_stack.pop() == 0:
                ip = instr[1]
        elif op == _OP_JMP:
            ip = instr[1]

    return ("ok", val_stack[0])

from bisect import bisect_left, bisect_right


def count_records(levels: list[int], margin: int, queries: list[tuple[int, int]]) -> list[int]:
    if not queries:
        return []

    n = len(levels)
    nxt = [n] * n
    st_idx: list[int] = []
    st_neg: list[int] = []

    for i in range(n - 1, -1, -1):
        val = levels[i]
        pos = bisect_right(st_neg, -(val + margin)) - 1
        if pos >= 0:
            nxt[i] = st_idx[pos]
        neg_val = -val
        while st_neg and st_neg[-1] >= neg_val:
            st_neg.pop()
            st_idx.pop()
        st_neg.append(neg_val)
        st_idx.append(i)

    children: list[list[int]] = [[] for _ in range(n + 1)]
    for i, p in enumerate(nxt):
        children[p].append(i)

    q_at: list[list[int]] = [[] for _ in range(n)]
    for qi, (l, _) in enumerate(queries):
        q_at[l].append(qi)

    ans = [0] * len(queries)
    path: list[int] = []
    stack = [n]

    while stack:
        u = stack.pop()
        if u < 0:
            path.pop()
            continue
        ch = children[u]
        if ch:
            path.append(-u)
            if u < n:
                ql = q_at[u]
                if ql:
                    plen = len(path)
                    for qi in ql:
                        ans[qi] = plen - bisect_left(path, -queries[qi][1])
            stack.append(~u)
            stack.extend(ch)
        else:
            ql = q_at[u]
            if ql:
                plen1 = len(path) + 1
                for qi in ql:
                    ans[qi] = plen1 - bisect_left(path, -queries[qi][1])

    return ans

import math
import re

_PRINCIPAL_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,6})?")


def amortize(principal: str, annual_rate_pct: str, months: int) -> list[tuple[str, str, str]]:
    if not isinstance(principal, str) or _PRINCIPAL_RE.fullmatch(principal) is None:
        raise ValueError("Invalid principal")
    if not isinstance(annual_rate_pct, str) or _RATE_RE.fullmatch(annual_rate_pct) is None:
        raise ValueError("Invalid annual_rate_pct")
    if not isinstance(months, int) or isinstance(months, bool) or not (1 <= months <= 1200):
        raise ValueError("Invalid months")

    if "." in principal:
        p_int, p_frac = principal.split(".")
        if len(p_frac) == 1:
            bal_cents = int(p_int) * 100 + int(p_frac) * 10
        else:
            bal_cents = int(p_int) * 100 + int(p_frac)
    else:
        bal_cents = int(principal) * 100

    if bal_cents <= 0:
        raise ValueError("principal must be > 0")

    if "." in annual_rate_pct:
        r_int_part, r_frac_part = annual_rate_pct.split(".")
        scale = 10 ** len(r_frac_part)
        r_scaled = int(r_int_part) * scale + int(r_frac_part)
    else:
        scale = 1
        r_scaled = int(annual_rate_pct)

    if r_scaled > 100 * scale:
        raise ValueError("annual_rate_pct must be <= 100")

    if r_scaled == 0:
        m_num = 0
        m_den = 1
        pay_cents = (bal_cents + months - 1) // months
    else:
        raw_den = 1200 * scale
        g = math.gcd(r_scaled, raw_den)
        m_num = r_scaled // g
        m_den = raw_den // g

        u = m_den + m_num
        v = m_den
        u_pow = pow(u, months)
        v_pow = pow(v, months)

        num = bal_cents * m_num * u_pow
        den = m_den * (u_pow - v_pow)
        pay_cents = (num + den - 1) // den

    def fmt(cents: int) -> str:
        dollars, rem = divmod(cents, 100)
        return f"{dollars}.{rem:02d}"

    schedule: list[tuple[str, str, str]] = []
    pay_str = fmt(pay_cents)

    for t in range(1, months + 1):
        if m_num == 0:
            interest_cents = 0
        else:
            q, r = divmod(bal_cents * m_num, m_den)
            twice_r = r << 1
            if twice_r > m_den or (twice_r == m_den and (q & 1)):
                interest_cents = q + 1
            else:
                interest_cents = q

        if t == months or bal_cents + interest_cents <= pay_cents:
            final_pay_cents = bal_cents + interest_cents
            schedule.append((fmt(final_pay_cents), fmt(interest_cents), "0.00"))
            break

        bal_cents -= pay_cents - interest_cents
        schedule.append((pay_str, fmt(interest_cents), fmt(bal_cents)))

    return schedule

import math

_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"
_BASE_CACHE: dict[int, tuple] = {}


def _get_base_data(base: int) -> tuple:
    cached = _BASE_CACHE.get(base)
    if cached is not None:
        return cached

    c = 1
    b1 = base
    while b1 * base <= 4096:
        b1 *= base
        c += 1

    digits = _DIGITS[:base]
    table_list = list(digits)
    for _ in range(c - 1):
        table_list = [s + d for s in table_list for d in digits]
    table = tuple(table_list)

    b2 = b1 * b1
    b4 = b2 * b2
    leaf_w = 8 * c

    m = leaf_w
    while m < 384:
        m <<= 1

    splits: dict[int, int] = {}
    zeros: dict[int, str] = {leaf_w: "0" * leaf_w}
    w = leaf_w * 2
    pw = base ** leaf_w
    while w <= m:
        splits[w] = pw
        zeros[w] = "0" * w
        pw *= pw
        w <<= 1

    big_b = base ** m
    data = (c, b1, b2, b4, table, leaf_w, m, big_b, splits, zeros)
    _BASE_CACHE[base] = data
    return data


def _int_to_base(n: int, b1: int, table: tuple[str, ...]) -> str:
    if n == 0:
        return "0"
    if n < b1:
        return table[n].lstrip("0")
    parts: list[str] = []
    while n >= b1:
        n, r = divmod(n, b1)
        parts.append(table[r])
    parts.append(table[n].lstrip("0"))
    parts.reverse()
    return "".join(parts)


def _emit_pow2_chunk(
    val: int,
    w: int,
    out_append,
    leaf_w: int,
    b1: int,
    b2: int,
    b4: int,
    table: tuple[str, ...],
    splits: dict[int, int],
    zeros: dict[int, str],
) -> None:
    if val == 0:
        out_append(zeros[w])
        return
    if w == leaf_w:
        hi4, lo4 = divmod(val, b4)
        hi2a, lo2a = divmod(hi4, b2)
        hi2b, lo2b = divmod(lo4, b2)
        a, b = divmod(hi2a, b1)
        e, f = divmod(lo2a, b1)
        g, h = divmod(hi2b, b1)
        i, j = divmod(lo2b, b1)
        out_append(f"{table[a]}{table[b]}{table[e]}{table[f]}{table[g]}{table[h]}{table[i]}{table[j]}")
        return
    half = w >> 1
    hi, lo = divmod(val, splits[w])
    _emit_pow2_chunk(hi, half, out_append, leaf_w, b1, b2, b4, table, splits, zeros)
    _emit_pow2_chunk(lo, half, out_append, leaf_w, b1, b2, b4, table, splits, zeros)


def _format_fixed_small(
    val: int, w: int, c: int, b1: int, table: tuple[str, ...]
) -> str:
    if val == 0:
        return "0" * w
    q_groups, rem_digits = divmod(w, c)
    parts = [""] * (q_groups + (1 if rem_digits else 0))
    idx = len(parts) - 1
    for _ in range(q_groups):
        val, r = divmod(val, b1)
        parts[idx] = table[r]
        idx -= 1
    if rem_digits:
        parts[0] = table[val][-rem_digits:]
    return "".join(parts)


def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0:
        raise ValueError("q must not be zero")
    if not (2 <= base <= 36):
        raise ValueError("base must be in 2..36")
    if k < 0:
        raise ValueError("k must be non-negative")

    if p == 0:
        return "0"

    neg = (p < 0) != (q < 0)
    P = -p if p < 0 else p
    Q = -q if q < 0 else q

    g = math.gcd(P, Q)
    if g > 1:
        P //= g
        Q //= g

    int_part, rem = divmod(P, Q)
    c, b1, b2, b4, table, leaf_w, m, big_b, splits, zeros = _get_base_data(base)

    if rem == 0:
        s = _int_to_base(int_part, b1, table)
        return "-" + s if neg else s

    if k == 0:
        two_rem = rem << 1
        if two_rem > Q or (two_rem == Q and (int_part & 1)):
            int_part += 1
        if int_part == 0:
            return "0"
        s = _int_to_base(int_part, b1, table)
        return "-" + s if neg else s

    n_full, rem_k = divmod(k, m)
    chunks: list[int] = []
    chunk_widths: list[int] = []
    R = rem

    for _ in range(n_full):
        q_chunk, R = divmod(R * big_b, Q)
        chunks.append(q_chunk)
        chunk_widths.append(m)
        if R == 0:
            break

    b_rem = 0
    if R != 0 and rem_k > 0:
        b_rem = base ** rem_k
        q_chunk, R = divmod(R * b_rem, Q)
        chunks.append(q_chunk)
        chunk_widths.append(rem_k)

    if R != 0:
        two_R = R << 1
        if two_R > Q:
            carry = 1
        elif two_R < Q:
            carry = 0
        else:
            int_scaled_parity = int_part & base & 1
            if (base & 1) == 0:
                q_frac_parity = chunks[-1] & 1
            else:
                q_frac_parity = 0
                for ch in chunks:
                    q_frac_parity ^= ch & 1
            carry = int_scaled_parity ^ q_frac_parity

        if carry:
            for i in range(len(chunks) - 1, -1, -1):
                limit = big_b if chunk_widths[i] == m else b_rem
                val = chunks[i] + 1
                if val < limit:
                    chunks[i] = val
                    carry = 0
                    break
                chunks[i] = 0
            if carry:
                int_part += 1

    while chunks and chunks[-1] == 0:
        chunks.pop()
        chunk_widths.pop()

    if not chunks:
        if int_part == 0:
            return "0"
        s = _int_to_base(int_part, b1, table)
        return "-" + s if neg else s

    out: list[str] = []
    if neg:
        out.append("-")
    out.append(_int_to_base(int_part, b1, table))
    out.append(".")

    last_idx = len(chunks) - 1
    out_append = out.append
    for i in range(last_idx):
        _emit_pow2_chunk(
            chunks[i], m, out_append, leaf_w, b1, b2, b4, table, splits, zeros
        )

    last_val = chunks[last_idx]
    last_w = chunk_widths[last_idx]
    if last_w == m:
        last_parts: list[str] = []
        _emit_pow2_chunk(
            last_val, m, last_parts.append, leaf_w, b1, b2, b4, table, splits, zeros
        )
        out.append("".join(last_parts).rstrip("0"))
    else:
        out.append(_format_fixed_small(last_val, last_w, c, b1, table).rstrip("0"))

    return "".join(out)

import math
import re

_LITERAL_RE = re.compile(
    r"([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?",
    re.ASCII,
)


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    if not isinstance(x, str):
        raise ValueError("x must be a string")
    if max_num < 0 or max_den < 1:
        raise ValueError("Invalid bounds: require max_num >= 0 and max_den >= 1")

    m = _LITERAL_RE.fullmatch(x)
    if m is None:
        raise ValueError(f"Invalid decimal literal: {x!r}")

    neg = m.group(1) == "-"
    int_part = m.group(2) or ""
    frac_part = m.group(3) if m.group(3) is not None else (m.group(4) or "")
    exp_str = m.group(5)
    exp = int(exp_str) if exp_str is not None else 0

    raw_digits = int_part + frac_part
    stripped = raw_digits.lstrip("0")
    if not stripped or max_num == 0:
        return "0/1"

    num_digits = stripped.rstrip("0")
    tz = len(stripped) - len(num_digits)
    e = exp - len(frac_part) + tz

    if e >= 0:
        if e > len(str(max_num)) + 5:
            return f"{-max_num if neg else max_num}/1"
        p = int(num_digits) * (10 ** e)
        q = 1
    else:
        neg_e = -e
        if neg_e - len(num_digits) > len(str(max_den)) + 2:
            return "0/1"
        p = int(num_digits)
        q = 10 ** neg_e
        g = math.gcd(p, q)
        if g > 1:
            p //= g
            q //= g

    # Accelerated Stern-Brocot / continued-fraction search within
    # 0 <= a <= max_num and 1 <= b <= max_den.
    # Maintain Farey neighbors L = a1/b1 < p/q < R = a2/b2 with a2*b1 - a1*b2 = 1.
    a1, b1 = 0, 1
    a2, b2 = 1, 0
    u = p  # p * b1 - a1 * q > 0
    v = q  # a2 * q - p * b2 > 0

    while a1 + a2 <= max_num and b1 + b2 <= max_den:
        if u == v:
            num, den = a1 + a2, b1 + b2
            break
        if u > v:
            k = u // v
            k_num = (max_num - a1) // a2
            if k_num < k:
                k = k_num
            if b2 > 0:
                k_den = (max_den - b1) // b2
                if k_den < k:
                    k = k_den
            a1 += k * a2
            b1 += k * b2
            u -= k * v
            if u == 0:
                num, den = a1, b1
                break
        else:
            k = v // u
            if a1 > 0:
                k_num = (max_num - a2) // a1
                if k_num < k:
                    k = k_num
            k_den = (max_den - b2) // b1
            if k_den < k:
                k = k_den
            a2 += k * a1
            b2 += k * b1
            v -= k * u
            if v == 0:
                num, den = a2, b2
                break
    else:
        if b2 == 0:
            num, den = a1, b1
        else:
            d_left = u * b2
            d_right = v * b1
            if d_left < d_right:
                num, den = a1, b1
            elif d_right < d_left:
                num, den = a2, b2
            elif b1 <= b2:
                num, den = a1, b1
            else:
                num, den = a2, b2

    if num == 0:
        return "0/1"
    if neg:
        num = -num
    return f"{num}/{den}"

import re

_LITERAL_RE = re.compile(
    r'\A([+-])?(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?\Z'
)
_FIVE_POW_25 = 5 ** 25  # 298023223876953125


def decimal_to_half_bits(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Expected a str")
    m = _LITERAL_RE.match(s)
    if m is None:
        raise ValueError(f"Invalid decimal literal: {s!r}")

    sign_bit = 0x8000 if m.group(1) == '-' else 0
    int_part = m.group(2) or ""
    frac_part = m.group(3) or m.group(4) or ""
    exp_str = m.group(5)

    int_nz = int_part.lstrip('0')
    if int_nz:
        p = len(int_nz) - 1
        first_in_int = True
        frac_nz = ""
    else:
        frac_nz = frac_part.lstrip('0')
        if not frac_nz:
            return sign_bit
        p = -(len(frac_part) - len(frac_nz) + 1)
        first_in_int = False

    if exp_str:
        exp_neg = False
        if exp_str[0] == '-':
            exp_neg = True
            exp_digits = exp_str[1:].lstrip('0')
        elif exp_str[0] == '+':
            exp_digits = exp_str[1:].lstrip('0')
        else:
            exp_digits = exp_str.lstrip('0')

        if not exp_digits:
            exp_val = 0
        elif len(exp_digits) > 12:
            return sign_bit if exp_neg else (sign_bit | 0x7C00)
        else:
            exp_val = int(exp_digits)
            if exp_neg:
                exp_val = -exp_val
    else:
        exp_val = 0

    e10 = p + exp_val
    if e10 >= 5:
        return sign_bit | 0x7C00
    if e10 <= -9:
        return sign_bit

    # Extract digits from the most significant non-zero digit down to 10^-25,
    # plus a sticky flag indicating whether any further non-zero digits exist.
    n = e10 + 26  # 18 <= n <= 30
    if first_in_int:
        if len(int_nz) >= n:
            digits_n = int_nz[:n]
            trailing = (
                int_nz.count('0', n) != len(int_nz) - n
                or frac_part.count('0') != len(frac_part)
            )
        else:
            rem = n - len(int_nz)
            if len(frac_part) >= rem:
                digits_n = int_nz + frac_part[:rem]
                trailing = frac_part.count('0', rem) != len(frac_part) - rem
            else:
                digits_n = int_nz + frac_part + '0' * (rem - len(frac_part))
                trailing = False
    else:
        if len(frac_nz) >= n:
            digits_n = frac_nz[:n]
            trailing = frac_nz.count('0', n) != len(frac_nz) - n
        else:
            digits_n = frac_nz + '0' * (n - len(frac_nz))
            trailing = False

    # v * 2^25 = (v_floor + eps) / 5^25, where 0 <= eps < 1 (eps > 0 iff trailing).
    # Thus q = floor(v * 2^25), and has_rem tells whether v * 2^25 > q.
    v_floor = int(digits_n)
    q, r = divmod(v_floor, _FIVE_POW_25)
    has_rem = trailing or (r > 0)

    if q >= (1 << 41):  # v >= 65536
        return sign_bit | 0x7C00

    if q < 2048:
        mant = q >> 1
        if (q & 1) and (has_rem or (mant & 1)):
            mant += 1
        return sign_bit | mant

    exp_bits = q.bit_length() - 11  # 1 <= exp_bits <= 30
    mant = q >> exp_bits
    low = q & ((1 << exp_bits) - 1)
    half = 1 << (exp_bits - 1)
    if low > half or (low == half and (has_rem or (mant & 1))):
        mant += 1

    return sign_bit | (((exp_bits - 1) << 10) + mant)

from bisect import bisect_left, bisect_right


def run_ops(ops: list[tuple]) -> list:
    keys_set = {op[2] for op in ops if op[0] == "set"}
    if not keys_set:
        out = []
        out_append = out.append
        for op in ops:
            if op[1] != 0:
                out_append("BADVER")
            else:
                kind = op[0]
                if kind == "del":
                    out_append("NOKEY")
                elif kind == "count" or kind == "sum":
                    out_append(0)
                else:
                    out_append(None)
        return out

    sorted_keys = sorted(keys_set)
    key_to_idx = {k: i for i, k in enumerate(sorted_keys)}
    m = len(sorted_keys)
    B = (m - 1).bit_length() if m > 1 else 1
    rev_bits = tuple((b, 1 << b) for b in range(B - 1, -1, -1))

    # Node 0 is the shared empty node
    left = [0]
    right = [0]
    cnt = [0]
    sm = [0]
    l_app = left.append
    r_app = right.append
    c_app = cnt.append
    s_app = sm.append

    roots = [0]
    path_nodes = [0] * B
    path_dirs = [0] * B

    out = []
    out_append = out.append

    for op in ops:
        v = op[1]
        if v < 0 or v >= len(roots):
            out_append("BADVER")
            continue

        kind = op[0]

        if kind == "set":
            idx = key_to_idx[op[2]]
            val = op[3]
            root = roots[v]
            cur = root
            for i in range(B):
                b = B - 1 - i
                path_nodes[i] = cur
                if (idx >> b) & 1:
                    path_dirs[i] = 1
                    cur = right[cur]
                else:
                    path_dirs[i] = 0
                    cur = left[cur]

            if cur != 0 and sm[cur] == val:
                roots.append(root)
            else:
                new_cur = len(cnt)
                l_app(0)
                r_app(0)
                c_app(1)
                s_app(val)
                for i in range(B - 1, -1, -1):
                    p = path_nodes[i]
                    if path_dirs[i]:
                        lc = left[p]
                        rc = new_cur
                    else:
                        lc = new_cur
                        rc = right[p]
                    new_cur = len(cnt)
                    l_app(lc)
                    r_app(rc)
                    c_app(cnt[lc] + cnt[rc])
                    s_app(sm[lc] + sm[rc])
                roots.append(new_cur)
            out_append(len(roots) - 1)

        elif kind == "del":
            idx = key_to_idx.get(op[2])
            if idx is None:
                out_append("NOKEY")
                continue
            cur = roots[v]
            for i in range(B):
                if cur == 0:
                    break
                b = B - 1 - i
                path_nodes[i] = cur
                if (idx >> b) & 1:
                    path_dirs[i] = 1
                    cur = right[cur]
                else:
                    path_dirs[i] = 0
                    cur = left[cur]

            if cur == 0:
                out_append("NOKEY")
            else:
                new_cur = 0
                for i in range(B - 1, -1, -1):
                    p = path_nodes[i]
                    if path_dirs[i]:
                        lc = left[p]
                        rc = new_cur
                    else:
                        lc = new_cur
                        rc = right[p]
                    nc = cnt[lc] + cnt[rc]
                    if nc == 0:
                        new_cur = 0
                    else:
                        new_cur = len(cnt)
                        l_app(lc)
                        r_app(rc)
                        c_app(nc)
                        s_app(sm[lc] + sm[rc])
                roots.append(new_cur)
                out_append(len(roots) - 1)

        elif kind == "get":
            idx = key_to_idx.get(op[2])
            if idx is None:
                out_append(None)
                continue
            node = roots[v]
            for b in range(B - 1, -1, -1):
                if node == 0:
                    break
                if (idx >> b) & 1:
                    node = right[node]
                else:
                    node = left[node]
            out_append(sm[node] if node else None)

        elif kind == "kth":
            node = roots[v]
            k = op[2]
            if k < 1 or k > cnt[node]:
                out_append(None)
                continue
            idx = 0
            for _, mask in rev_bits:
                lc = left[node]
                c = cnt[lc]
                if k <= c:
                    node = lc
                else:
                    k -= c
                    node = right[node]
                    idx |= mask
            out_append(sorted_keys[idx])

        else:  # "count" or "sum"
            lo = op[2]
            hi = op[3]
            if lo > hi:
                out_append(0)
                continue
            node = roots[v]
            if node == 0:
                out_append(0)
                continue
            l_idx = bisect_left(sorted_keys, lo)
            r_idx = bisect_right(sorted_keys, hi) - 1
            if l_idx > r_idx:
                out_append(0)
                continue

            arr = cnt if kind == "count" else sm

            if l_idx == r_idx:
                for b in range(B - 1, -1, -1):
                    if (l_idx >> b) & 1:
                        node = right[node]
                    else:
                        node = left[node]
                    if node == 0:
                        break
                out_append(arr[node])
                continue

            b = B - 1
            while b >= 0 and ((l_idx >> b) & 1) == ((r_idx >> b) & 1):
                if (l_idx >> b) & 1:
                    node = right[node]
                else:
                    node = left[node]
                if node == 0:
                    break
                b -= 1
            if node == 0:
                out_append(0)
                continue

            ans = 0
            lnode = left[node]
            for lb in range(b - 1, -1, -1):
                if lnode == 0:
                    break
                if (l_idx >> lb) & 1:
                    lnode = right[lnode]
                else:
                    ans += arr[right[lnode]]
                    lnode = left[lnode]
            else:
                ans += arr[lnode]

            rnode = right[node]
            for rb in range(b - 1, -1, -1):
                if rnode == 0:
                    break
                if (r_idx >> rb) & 1:
                    ans += arr[left[rnode]]
                    rnode = right[rnode]
                else:
                    rnode = left[rnode]
            else:
                ans += arr[rnode]

            out_append(ans)

    return out

from bisect import bisect_left


def run_ops(ops: list[tuple]) -> list:
    added_vals = {op[1] for op in ops if op[0] == "add"}
    out = []

    if not added_vals:
        cp_valid = [False]
        active_cps = []
        for op in ops:
            kind = op[0]
            if kind == "remove":
                out.append(False)
            elif kind == "checkpoint":
                cid = len(cp_valid)
                cp_valid.append(True)
                active_cps.append(cid)
                out.append(cid)
            elif kind == "rollback":
                c = op[1]
                if 1 <= c < len(cp_valid) and cp_valid[c]:
                    while active_cps[-1] > c:
                        cp_valid[active_cps.pop()] = False
                    out.append(0)
                else:
                    out.append("BADCP")
            elif kind == "median":
                out.append(None)
            elif kind == "count_less":
                out.append(0)
            elif kind == "distinct":
                out.append(0)
        return out

    vals = sorted(added_vals)
    n = len(vals)
    val_to_idx = {v: i for i, v in enumerate(vals)}
    max_pow2 = 1 << (n.bit_length() - 1)

    bit = [0] * (n + 1)
    freq = [0] * n
    size = 0
    distinct = 0

    undo = []
    cp_pos = [-1]
    active_cps = []

    for op in ops:
        kind = op[0]
        if kind == "add":
            idx = val_to_idx[op[1]]
            if freq[idx] == 0:
                distinct += 1
            freq[idx] += 1
            size += 1
            j = idx + 1
            while j <= n:
                bit[j] += 1
                j += j & -j
            undo.append(idx)
            out.append(size)

        elif kind == "remove":
            idx = val_to_idx.get(op[1])
            if idx is None or freq[idx] == 0:
                out.append(False)
            else:
                freq[idx] -= 1
                if freq[idx] == 0:
                    distinct -= 1
                size -= 1
                j = idx + 1
                while j <= n:
                    bit[j] -= 1
                    j += j & -j
                undo.append(~idx)
                out.append(True)

        elif kind == "checkpoint":
            cid = len(cp_pos)
            cp_pos.append(len(undo))
            active_cps.append(cid)
            out.append(cid)

        elif kind == "rollback":
            c = op[1]
            if 1 <= c < len(cp_pos) and cp_pos[c] != -1:
                target = cp_pos[c]
                while len(undo) > target:
                    code = undo.pop()
                    if code >= 0:
                        idx = code
                        freq[idx] -= 1
                        if freq[idx] == 0:
                            distinct -= 1
                        size -= 1
                        j = idx + 1
                        while j <= n:
                            bit[j] -= 1
                            j += j & -j
                    else:
                        idx = ~code
                        if freq[idx] == 0:
                            distinct += 1
                        freq[idx] += 1
                        size += 1
                        j = idx + 1
                        while j <= n:
                            bit[j] += 1
                            j += j & -j
                while active_cps[-1] > c:
                    cp_pos[active_cps.pop()] = -1
                out.append(size)
            else:
                out.append("BADCP")

        elif kind == "median":
            if size == 0:
                out.append(None)
            else:
                k = (size + 1) >> 1
                idx = 0
                step = max_pow2
                while step:
                    nxt = idx + step
                    if nxt <= n and bit[nxt] < k:
                        idx = nxt
                        k -= bit[nxt]
                    step >>= 1
                out.append(vals[idx])

        elif kind == "count_less":
            if size == 0:
                out.append(0)
            else:
                x = op[1]
                i = val_to_idx.get(x)
                if i is None:
                    i = bisect_left(vals, x)
                if i == 0:
                    out.append(0)
                elif i == n:
                    out.append(size)
                else:
                    s = 0
                    j = i
                    while j > 0:
                        s += bit[j]
                        j -= j & -j
                    out.append(s)

        elif kind == "distinct":
            out.append(distinct)

    return out

from bisect import bisect_right
from collections import defaultdict


def run_ops(ops: list[tuple]) -> list:
    MIN_BLOCK = 256
    MAX_BLOCK = 1024

    b_starts: list[list[int]] = []
    b_ends: list[list[int]] = []
    b_labels: list[list[str]] = []
    mins: list[int] = []

    total_runs = 0
    totals: dict[str, int] = defaultdict(int)

    def find_gt(x: int) -> tuple[int, int]:
        if not b_starts:
            return (0, 0)
        bi = bisect_right(mins, x) - 1
        if bi < 0:
            return (0, 0)
        ii = bisect_right(b_starts[bi], x)
        if ii == len(b_starts[bi]):
            return (bi + 1, 0)
        return (bi, ii)

    def prev_pos(bi: int, ii: int):
        if ii > 0:
            return (bi, ii - 1)
        if bi > 0:
            return (bi - 1, len(b_starts[bi - 1]) - 1)
        return None

    def next_pos(bi: int, ii: int) -> tuple[int, int]:
        if ii + 1 < len(b_starts[bi]):
            return (bi, ii + 1)
        return (bi + 1, 0)

    def fix_block(bi: int) -> None:
        n = len(b_starts[bi])
        if n == 0:
            del b_starts[bi], b_ends[bi], b_labels[bi], mins[bi]
            return
        if n > MAX_BLOCK:
            mid = n >> 1
            b_starts.insert(bi + 1, b_starts[bi][mid:])
            b_ends.insert(bi + 1, b_ends[bi][mid:])
            b_labels.insert(bi + 1, b_labels[bi][mid:])
            del b_starts[bi][mid:], b_ends[bi][mid:], b_labels[bi][mid:]
            mins.insert(bi + 1, b_starts[bi + 1][0])
            return
        if n < MIN_BLOCK:
            if bi + 1 < len(b_starts):
                b_starts[bi].extend(b_starts[bi + 1])
                b_ends[bi].extend(b_ends[bi + 1])
                b_labels[bi].extend(b_labels[bi + 1])
                del b_starts[bi + 1], b_ends[bi + 1], b_labels[bi + 1], mins[bi + 1]
                if len(b_starts[bi]) > MAX_BLOCK:
                    mid = len(b_starts[bi]) >> 1
                    b_starts.insert(bi + 1, b_starts[bi][mid:])
                    b_ends.insert(bi + 1, b_ends[bi][mid:])
                    b_labels.insert(bi + 1, b_labels[bi][mid:])
                    del b_starts[bi][mid:], b_ends[bi][mid:], b_labels[bi][mid:]
                    mins.insert(bi + 1, b_starts[bi + 1][0])
            elif bi > 0:
                b_starts[bi - 1].extend(b_starts[bi])
                b_ends[bi - 1].extend(b_ends[bi])
                b_labels[bi - 1].extend(b_labels[bi])
                del b_starts[bi], b_ends[bi], b_labels[bi], mins[bi]
                if len(b_starts[bi - 1]) > MAX_BLOCK:
                    mid = len(b_starts[bi - 1]) >> 1
                    b_starts.insert(bi, b_starts[bi - 1][mid:])
                    b_ends.insert(bi, b_ends[bi - 1][mid:])
                    b_labels.insert(bi, b_labels[bi - 1][mid:])
                    del b_starts[bi - 1][mid:], b_ends[bi - 1][mid:], b_labels[bi - 1][mid:]
                    mins.insert(bi, b_starts[bi][0])

    def splice(
        lo_pos: tuple[int, int],
        hi_pos: tuple[int, int],
        new_items: list[tuple[int, int, str]],
    ) -> None:
        nonlocal total_runs
        lbi, lii = lo_pos
        rbi, rii = hi_pos

        deleted_cnt = 0
        if lbi == rbi:
            if lii < rii:
                bs = b_starts[lbi]
                be = b_ends[lbi]
                bl = b_labels[lbi]
                for k in range(lii, rii):
                    totals[bl[k]] -= be[k] - bs[k]
                deleted_cnt = rii - lii
        else:
            bs = b_starts[lbi]
            be = b_ends[lbi]
            bl = b_labels[lbi]
            n0 = len(bs)
            for k in range(lii, n0):
                totals[bl[k]] -= be[k] - bs[k]
            deleted_cnt = n0 - lii

            for b in range(lbi + 1, rbi):
                bs = b_starts[b]
                be = b_ends[b]
                bl = b_labels[b]
                deleted_cnt += len(bs)
                for k in range(len(bs)):
                    totals[bl[k]] -= be[k] - bs[k]

            if rii > 0:
                bs = b_starts[rbi]
                be = b_ends[rbi]
                bl = b_labels[rbi]
                deleted_cnt += rii
                for k in range(rii):
                    totals[bl[k]] -= be[k] - bs[k]

        for s, e, lbl in new_items:
            totals[lbl] += e - s
        total_runs += len(new_items) - deleted_cnt

        ns = [x[0] for x in new_items]
        ne = [x[1] for x in new_items]
        nl = [x[2] for x in new_items]

        if lbi == rbi:
            if lbi == len(b_starts):
                if new_items:
                    b_starts.append(ns)
                    b_ends.append(ne)
                    b_labels.append(nl)
                    mins.append(ns[0])
            else:
                b_starts[lbi][lii:rii] = ns
                b_ends[lbi][lii:rii] = ne
                b_labels[lbi][lii:rii] = nl
                if b_starts[lbi]:
                    mins[lbi] = b_starts[lbi][0]
                fix_block(lbi)
        else:
            rbi_survived = False
            if rbi < len(b_starts):
                if rii > 0:
                    del b_starts[rbi][:rii]
                    del b_ends[rbi][:rii]
                    del b_labels[rbi][:rii]
                if b_starts[rbi]:
                    mins[rbi] = b_starts[rbi][0]
                    rbi_survived = True
                else:
                    del b_starts[rbi], b_ends[rbi], b_labels[rbi], mins[rbi]

            if lbi + 1 < rbi:
                del b_starts[lbi + 1 : rbi]
                del b_ends[lbi + 1 : rbi]
                del b_labels[lbi + 1 : rbi]
                del mins[lbi + 1 : rbi]

            lbi_survived = False
            b_starts[lbi][lii:] = ns
            b_ends[lbi][lii:] = ne
            b_labels[lbi][lii:] = nl
            if b_starts[lbi]:
                mins[lbi] = b_starts[lbi][0]
                lbi_survived = True
            else:
                del b_starts[lbi], b_ends[lbi], b_labels[lbi], mins[lbi]

            if rbi_survived:
                fix_block(lbi + 1 if lbi_survived else lbi)
            if lbi_survived:
                fix_block(lbi)

    out = []
    for op in ops:
        kind = op[0]
        if kind == "paint":
            _, l, r, label = op
            if l >= r:
                out.append(0)
                continue

            lo_pos = find_gt(l)
            p = prev_pos(*lo_pos)
            if p is not None and b_ends[p[0]][p[1]] > l:
                lo_pos = p
            hi_pos = find_gt(r - 1)

            lo_orig = lo_pos
            hi_orig = hi_pos

            changed = r - l
            if lo_orig < hi_orig:
                lbi, lii = lo_orig
                rbi, rii = hi_orig
                if lbi == rbi:
                    bs = b_starts[lbi]
                    be = b_ends[lbi]
                    bl = b_labels[lbi]
                    for k in range(lii, rii):
                        if bl[k] == label:
                            s = bs[k] if bs[k] > l else l
                            e = be[k] if be[k] < r else r
                            changed -= e - s
                else:
                    bs = b_starts[lbi]
                    be = b_ends[lbi]
                    bl = b_labels[lbi]
                    for k in range(lii, len(bs)):
                        if bl[k] == label:
                            s = bs[k] if bs[k] > l else l
                            e = be[k] if be[k] < r else r
                            changed -= e - s
                    for b in range(lbi + 1, rbi):
                        bs = b_starts[b]
                        be = b_ends[b]
                        bl = b_labels[b]
                        for k in range(len(bs)):
                            if bl[k] == label:
                                changed -= be[k] - bs[k]
                    if rii > 0:
                        bs = b_starts[rbi]
                        be = b_ends[rbi]
                        bl = b_labels[rbi]
                        for k in range(rii):
                            if bl[k] == label:
                                s = bs[k] if bs[k] > l else l
                                e = be[k] if be[k] < r else r
                                changed -= e - s

            if changed == 0:
                out.append(0)
                continue

            new_l = l
            new_r = r
            left_rem = None
            right_rem = None

            if lo_orig < hi_orig and b_starts[lo_orig[0]][lo_orig[1]] < l:
                lbi, lii = lo_orig
                if b_labels[lbi][lii] == label:
                    new_l = b_starts[lbi][lii]
                else:
                    left_rem = (b_starts[lbi][lii], l, b_labels[lbi][lii])
            else:
                p = prev_pos(*lo_orig)
                if p is not None and b_ends[p[0]][p[1]] == l and b_labels[p[0]][p[1]] == label:
                    new_l = b_starts[p[0]][p[1]]
                    lo_pos = p

            if lo_orig < hi_orig:
                pr = prev_pos(*hi_orig)
                rbi, rii = pr
                if b_ends[rbi][rii] > r:
                    if b_labels[rbi][rii] == label:
                        new_r = b_ends[rbi][rii]
                    else:
                        right_rem = (r, b_ends[rbi][rii], b_labels[rbi][rii])
                elif (
                    hi_orig[0] < len(b_starts)
                    and b_starts[hi_orig[0]][hi_orig[1]] == r
                    and b_labels[hi_orig[0]][hi_orig[1]] == label
                ):
                    new_r = b_ends[hi_orig[0]][hi_orig[1]]
                    hi_pos = next_pos(*hi_orig)
            else:
                if (
                    hi_orig[0] < len(b_starts)
                    and b_starts[hi_orig[0]][hi_orig[1]] == r
                    and b_labels[hi_orig[0]][hi_orig[1]] == label
                ):
                    new_r = b_ends[hi_orig[0]][hi_orig[1]]
                    hi_pos = next_pos(*hi_orig)

            new_items = []
            if left_rem is not None:
                new_items.append(left_rem)
            new_items.append((new_l, new_r, label))
            if right_rem is not None:
                new_items.append(right_rem)

            splice(lo_pos, hi_pos, new_items)
            out.append(changed)

        elif kind == "erase":
            _, l, r = op
            if l >= r:
                out.append(0)
                continue

            lo_pos = find_gt(l)
            p = prev_pos(*lo_pos)
            if p is not None and b_ends[p[0]][p[1]] > l:
                lo_pos = p
            hi_pos = find_gt(r - 1)

            if lo_pos == hi_pos:
                out.append(0)
                continue

            changed = 0
            lbi, lii = lo_pos
            rbi, rii = hi_pos
            if lbi == rbi:
                bs = b_starts[lbi]
                be = b_ends[lbi]
                for k in range(lii, rii):
                    s = bs[k] if bs[k] > l else l
                    e = be[k] if be[k] < r else r
                    changed += e - s
            else:
                bs = b_starts[lbi]
                be = b_ends[lbi]
                for k in range(lii, len(bs)):
                    s = bs[k] if bs[k] > l else l
                    e = be[k] if be[k] < r else r
                    changed += e - s
                for b in range(lbi + 1, rbi):
                    bs = b_starts[b]
                    be = b_ends[b]
                    for k in range(len(bs)):
                        changed += be[k] - bs[k]
                if rii > 0:
                    bs = b_starts[rbi]
                    be = b_ends[rbi]
                    for k in range(rii):
                        s = bs[k] if bs[k] > l else l
                        e = be[k] if be[k] < r else r
                        changed += e - s

            new_items = []
            if b_starts[lbi][lii] < l:
                new_items.append((b_starts[lbi][lii], l, b_labels[lbi][lii]))
            pr = prev_pos(*hi_pos)
            if b_ends[pr[0]][pr[1]] > r:
                new_items.append((r, b_ends[pr[0]][pr[1]], b_labels[pr[0]][pr[1]]))

            splice(lo_pos, hi_pos, new_items)
            out.append(changed)

        elif kind == "at":
            p = op[1]
            bi, ii = find_gt(p)
            pr = prev_pos(bi, ii)
            if pr is not None and b_ends[pr[0]][pr[1]] > p:
                out.append(b_labels[pr[0]][pr[1]])
            else:
                out.append(None)

        elif kind == "runs":
            out.append(total_runs)

        elif kind == "total":
            out.append(totals.get(op[1], 0))

        elif kind == "next_change":
            p = op[1]
            bi, ii = find_gt(p)
            pr = prev_pos(bi, ii)
            if pr is not None and b_ends[pr[0]][pr[1]] > p:
                out.append(b_ends[pr[0]][pr[1]])
            elif bi < len(b_starts):
                out.append(b_starts[bi][ii])
            else:
                out.append(None)

    return out

from collections import OrderedDict
from heapq import heappop, heappush


def run_cache(capacity, ops):
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, seq]; oldest use first
    expiry_heap = []  # min-heap of (expires_at, seq, key)
    out = []
    last_t = None
    seq = 0

    def purge(t):
        while expiry_heap and expiry_heap[0][0] <= t:
            _, exp_seq, exp_key = heappop(expiry_heap)
            entry = store.get(exp_key)
            if entry is not None and entry[1] == exp_seq:
                del store[exp_key]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (
                isinstance(ttl, bool) or not isinstance(ttl, int) or ttl < 1
            ):
                raise ValueError("ttl must be None or a positive int")

            if expiry_heap and expiry_heap[0][0] <= t:
                purge(t)

            seq += 1
            entry = store.get(key)
            if entry is not None:
                entry[0] = value
                entry[1] = seq
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = [value, seq]

            if ttl is not None:
                heappush(expiry_heap, (t + ttl, seq, key))

        elif kind == "get":
            key = op[2]
            if expiry_heap and expiry_heap[0][0] <= t:
                purge(t)

            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            if expiry_heap and expiry_heap[0][0] <= t:
                purge(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

import heapq


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    heappush = heapq.heappush
    heappop = heapq.heappop

    low = []    # max-heap via negation: the smaller half, its top is the median
    high = []   # min-heap: the larger half
    delayed = {}  # value -> pending lazy deletion count
    low_size = 0
    high_size = 0
    out = []

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap:
            val = sign * heap[0]
            cnt = delayed.get(val, 0)
            if not cnt:
                break
            if cnt == 1:
                del delayed[val]
            else:
                delayed[val] = cnt - 1
            heappop(heap)

    def rebalance():
        nonlocal low_size, high_size
        # invariant: low_size == high_size or low_size == high_size + 1
        if low_size > high_size + 1:
            heappush(high, -heappop(low))
            low_size -= 1
            high_size += 1
            prune(low, -1)
        elif low_size < high_size:
            heappush(low, -heappop(high))
            high_size -= 1
            low_size += 1
            prune(high, 1)

    def add(x):
        nonlocal low_size, high_size
        if not low or x <= -low[0]:
            heappush(low, -x)
            low_size += 1
        else:
            heappush(high, x)
            high_size += 1
        rebalance()

    def remove(x):
        nonlocal low_size, high_size
        delayed[x] = delayed.get(x, 0) + 1
        if x <= -low[0]:
            low_size -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            high_size -= 1
            if x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k:
            old = readings[i - k]
            if old is not None:
                remove(old)
        out.append(-low[0] if low_size else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            i = n if end == -1 else end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
